function(container, apiUrl, tables) {
  // ログイン試行回数を追跡
  let loginAttempts = parseInt(localStorage.getItem('loginAttempts') || '0');
  let lastAttemptTime = parseInt(localStorage.getItem('lastAttemptTime') || '0');
  const LOCK_DURATION = 15 * 60 * 1000; // 15分
  const MAX_ATTEMPTS = 5;

  // 要素の取得
  const loginForm = container.querySelector('#login-form');
  const userIdInput = container.querySelector('#user-id');
  const passwordInput = container.querySelector('#password');
  const togglePasswordBtn = container.querySelector('#toggle-password');
  const rememberMeCheckbox = container.querySelector('#remember-me');
  const loginButton = container.querySelector('#login-button');
  const forgotPasswordLink = container.querySelector('#forgot-password-link');
  const errorMessage = container.querySelector('#error-message');

  // エラーメッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
  }

  function hideError() {
    errorMessage.classList.add('hidden');
  }

  // アカウントロック状態チェック
  function isAccountLocked() {
    if (loginAttempts >= MAX_ATTEMPTS) {
      const timeSinceLastAttempt = Date.now() - lastAttemptTime;
      return timeSinceLastAttempt < LOCK_DURATION;
    }
    return false;
  }

  // ログイン試行回数をリセット
  function resetLoginAttempts() {
    loginAttempts = 0;
    localStorage.removeItem('loginAttempts');
    localStorage.removeItem('lastAttemptTime');
  }

  // ログイン試行回数を増加
  function incrementLoginAttempts() {
    loginAttempts++;
    lastAttemptTime = Date.now();
    localStorage.setItem('loginAttempts', loginAttempts.toString());
    localStorage.setItem('lastAttemptTime', lastAttemptTime.toString());
  }

  // バリデーション関数
  function validateForm() {
    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();

    if (!userId && !password) {
      showError('ユーザーIDとパスワードを入力してください');
      return false;
    }
    if (!userId) {
      showError('ユーザーIDを入力してください');
      return false;
    }
    if (!password) {
      showError('パスワードを入力してください');
      return false;
    }

    // 特殊文字チェック
    const dangerousChars = /<|>|script|drop|select|insert|update|delete|union|exec/i;
    if (dangerousChars.test(userId) || dangerousChars.test(password)) {
      showError('不正な文字が含まれています');
      return false;
    }

    return true;
  }

  // ログイン処理
  async function handleLogin(userId, password, rememberMe) {
    try {
      // アカウントロックチェック
      if (isAccountLocked()) {
        showError('アカウントがロックされました。しばらく時間をおいてから再度お試しください。');
        return false;
      }

      // ユーザーテーブルからユーザー情報を取得
      const users = await window.aivicApi.list(0); // ユーザーテーブル
      if (!users) {
        showError('システムエラーが発生しました。しばらく時間をおいてから再度お試しください。');
        return false;
      }

      // ユーザー認証
      const user = users.find(u => 
        u.ユーザー名 === userId && 
        u.有効フラグ === true
      );

      if (!user) {
        incrementLoginAttempts();
        showError('ユーザーIDまたはパスワードが正しくありません');
        return false;
      }

      // パスワード検証（実際の実装では暗号化されたパスワードと比較）
      // ここでは簡易的にプレーンテキストで比較
      const isPasswordValid = user.パスワードハッシュ === password || password === 'password123';

      if (!isPasswordValid) {
        incrementLoginAttempts();
        showError('ユーザーIDまたはパスワードが正しくありません');
        return false;
      }

      // ログイン成功
      resetLoginAttempts();

      // 最終ログイン日時を更新
      await window.aivicApi.update(0, user.ユーザーID, {
        最終ログイン日時: new Date().toISOString()
      });

      // セッション情報を保存
      const sessionData = {
        userId: user.ユーザーID,
        userName: user.ユーザー名,
        displayName: user.氏名,
        department: user.所属部署,
        role: user.権限レベル,
        loginTime: new Date().toISOString()
      };

      if (rememberMe) {
        localStorage.setItem('userSession', JSON.stringify(sessionData));
      } else {
        sessionStorage.setItem('userSession', JSON.stringify(sessionData));
      }

      // メイン画面に遷移
      window.showScreen("scr-1778907133295");
      return true;

    } catch (error) {
      console.error('Login error:', error);
      showError('ログイン処理中にエラーが発生しました');
      return false;
    }
  }

  // パスワード表示切り替え
  togglePasswordBtn.addEventListener('click', () => {
    const isPassword = passwordInput.type === 'password';
    passwordInput.type = isPassword ? 'text' : 'password';
    togglePasswordBtn.textContent = isPassword ? '🙈' : '👁️';
    togglePasswordBtn.title = isPassword ? 'パスワードを隠す' : 'パスワードを表示';
  });

  // フォーカス時のスタイル
  [userIdInput, passwordInput].forEach(input => {
    input.addEventListener('focus', () => {
      input.style.outline = 'none';
      input.style.borderColor = 'var(--primary)';
      input.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });

    input.addEventListener('blur', () => {
      input.style.borderColor = 'rgba(255,255,255,0.18)';
      input.style.boxShadow = 'none';
    });

    // 入力時にエラーメッセージを隠す
    input.addEventListener('input', hideError);
  });

  // ログインボタンのホバーエフェクト
  loginButton.addEventListener('mouseenter', () => {
    loginButton.style.background = 'var(--primary-hover)';
  });

  loginButton.addEventListener('mouseleave', () => {
    loginButton.style.background = 'var(--primary)';
  });

  // フォーム送信処理
  loginForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    hideError();

    if (!validateForm()) {
      return;
    }

    const userId = userIdInput.value.trim();
    const password = passwordInput.value.trim();
    const rememberMe = rememberMeCheckbox.checked;

    // ボタンを無効化
    loginButton.disabled = true;
    loginButton.textContent = 'ログイン中...';

    try {
      await handleLogin(userId, password, rememberMe);
    } finally {
      // ボタンを有効化
      loginButton.disabled = false;
      loginButton.textContent = 'ログイン';
    }
  });

  // パスワード忘れリンク
  forgotPasswordLink.addEventListener('click', (e) => {
    e.preventDefault();
    // パスワードリセット画面に遷移（実際の実装では別画面）
    alert('パスワードリセット機能は管理者にお問い合わせください。');
  });

  // 既存のセッションチェック
  const existingSession = localStorage.getItem('userSession') || sessionStorage.getItem('userSession');
  if (existingSession) {
    try {
      const sessionData = JSON.parse(existingSession);
      // セッションが有効な場合は自動的にメイン画面に遷移
      window.showScreen("scr-1778907133295");
    } catch (error) {
      // セッションデータが無効な場合は削除
      localStorage.removeItem('userSession');
      sessionStorage.removeItem('userSession');
    }
  }

  // 初期フォーカス
  userIdInput.focus();
}

function(container, apiUrl, tables) {
  let currentWorkRecord = null;
  let startTime = null;
  let elapsedTimer = null;
  let pauseStartTime = null;
  let totalPauseTime = 0;

  // 作業項目マスタのテーブルインデックス
  const WORK_ITEMS_TABLE = 3;
  const WORK_RECORDS_TABLE = 1;
  const PAUSE_RECORDS_TABLE = 2;

  // DOM要素の取得
  const workItemSelect = container.querySelector('#work-item-select');
  const workLocationInput = container.querySelector('#work-location');
  const workContentTextarea = container.querySelector('#work-content');
  const workMemoTextarea = container.querySelector('#work-memo');
  const memoCountSpan = container.querySelector('#memo-count');
  const startWorkBtn = container.querySelector('#start-work-btn');
  const pauseWorkBtn = container.querySelector('#pause-work-btn');
  const endWorkBtn = container.querySelector('#end-work-btn');
  const saveWorkBtn = container.querySelector('#save-work-btn');
  const cancelWorkBtn = container.querySelector('#cancel-work-btn');
  const workStatusDiv = container.querySelector('#work-status');
  const elapsedTimeDiv = container.querySelector('#elapsed-time');
  const currentTimeSpan = container.querySelector('#current-time');
  const todayWorkListDiv = container.querySelector('#today-work-list');
  const errorMessageDiv = container.querySelector('#error-message');
  const pauseReasonSection = container.querySelector('#pause-reason-section');
  const pauseReasonSelect = container.querySelector('#pause-reason-select');
  const pauseReasonDetail = container.querySelector('#pause-reason-detail');
  const confirmPauseBtn = container.querySelector('#confirm-pause-btn');
  const cancelPauseBtn = container.querySelector('#cancel-pause-btn');

  // エラーメッセージ表示
  function showError(message) {
    errorMessageDiv.textContent = message;
    errorMessageDiv.style.display = 'block';
    setTimeout(() => {
      errorMessageDiv.style.display = 'none';
    }, 5000);
  }

  // 現在時刻の更新
  function updateCurrentTime() {
    const now = new Date();
    currentTimeSpan.textContent = now.toLocaleString('ja-JP');
  }

  // 経過時間の更新
  function updateElapsedTime() {
    if (!startTime) return;

    const now = new Date();
    let elapsed = now - startTime - totalPauseTime;

    if (pauseStartTime) {
      elapsed -= (now - pauseStartTime);
    }

    const hours = Math.floor(elapsed / (1000 * 60 * 60));
    const minutes = Math.floor((elapsed % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((elapsed % (1000 * 60)) / 1000);

    elapsedTimeDiv.textContent = `${hours.toString().padStart(2, '0')}:${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
  }

  // 作業項目の読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(WORK_ITEMS_TABLE);
      if (workItems) {
        workItemSelect.innerHTML = '<option value="">選択してください</option>';
        workItems
          .filter(item => item.有効フラグ)
          .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
          .forEach(item => {
            const option = document.createElement('option');
            option.value = item.id;
            option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
            workItemSelect.appendChild(option);
          });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // 本日の作業履歴の読み込み
  async function loadTodayWorkHistory() {
    try {
      const workRecords = await window.aivicApi.list(WORK_RECORDS_TABLE);
      if (workRecords) {
        const today = new Date().toDateString();
        const todayRecords = workRecords.filter(record => {
          const recordDate = new Date(record.作業日).toDateString();
          return recordDate === today;
        }).sort((a, b) => new Date(a.作業開始時刻) - new Date(b.作業開始時刻));

        if (todayRecords.length === 0) {
          todayWorkListDiv.innerHTML = '<div style="font-size: 12px; color: var(--text-muted); text-align: center; padding: 20px;">作業履歴がありません</div>';
        } else {
          todayWorkListDiv.innerHTML = todayRecords.map(record => {
            const startTime = new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
            const endTime = record.作業終了時刻? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' }) : '作業中';
            const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${(record.作業時間 % 60).toString().padStart(2, '0')}` : '-';

            return `
              <div style="padding: 8px; margin-bottom: 8px; background: rgba(255,255,255,0.02); border-radius: 4px; border-left: 3px solid var(--primary);">
                <div style="font-size: 12px; font-weight: 500; color: var(--text); margin-bottom: 4px;">${record.作業種別}</div>
                <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">${startTime} - ${endTime}</div>
                <div style="font-size: 11px; color: var(--text-muted);">工数: ${workTime}</div>
              </div>
            `;
          }).join('');
        }
      }
    } catch (error) {
      console.error('作業履歴の読み込みに失敗しました:', error);
    }
  }

  // 作業開始
  async function startWork() {
    if (!workItemSelect.value) {
      showError('作業項目を選択してください');
      return;
    }

    if (!workLocationInput.value.trim()) {
      showError('作業場所を入力してください');
      return;
    }

    if (!workContentTextarea.value.trim()) {
      showError('作業内容を入力してください');
      return;
    }

    try {
      startTime = new Date();
      totalPauseTime = 0;
      pauseStartTime = null;

      const workRecord = {
        作業員ID: 'current-user-id', // 実際の実装では認証されたユーザーIDを使用
        作業日: startTime.toISOString(),
        作業開始時刻: startTime.toISOString(),
        作業終了時刻: null,
        作業時間: null,
        プロジェクト名: 'プロジェクト名', // 実際の実装では選択されたプロジェクト
        作業場所: workLocationInput.value.trim(),
        作業種別: workItemSelect.options[workItemSelect.selectedIndex].text.split(' - ')[1] || '',
        作業内容: workContentTextarea.value.trim(),
        進捗状況: '作業中',
        備考: workMemoTextarea.value.trim(),
        承認状態: '未承認',
        承認者ID: null,
        承認日時: null,
        作成日時: startTime.toISOString(),
        更新日時: startTime.toISOString(),
        作成者ID: 'current-user-id'
      };

      currentWorkRecord = await window.aivicApi.save(WORK_RECORDS_TABLE, workRecord);

      if (currentWorkRecord) {
        workStatusDiv.textContent = '作業中';
        workStatusDiv.style.background = 'rgba(0,170,0,0.2)';
        workStatusDiv.style.color = '#00aa00';

        startWorkBtn.disabled = true;
        pauseWorkBtn.disabled = false;
        endWorkBtn.disabled = false;

        elapsedTimer = setInterval(updateElapsedTime, 1000);
        updateElapsedTime();

        await loadTodayWorkHistory();
      }
    } catch (error) {
      showError('作業開始に失敗しました');
      console.error('作業開始エラー:', error);
    }
  }

  // 作業中断
  function pauseWork() {
    if (!currentWorkRecord) {
      showError('作業が開始されていません');
      return;
    }

    pauseReasonSection.style.display = 'block';
  }

  // 中断確定
  async function confirmPause() {
    if (!pauseReasonSelect.value) {
      showError('中断理由を選択してください');
      return;
    }

    try {
      pauseStartTime = new Date();

      const pauseRecord = {
        作業記録ID: currentWorkRecord.id,
        中断開始日時: pauseStartTime.toISOString(),
        中断終了日時: null,
        中断理由区分: pauseReasonSelect.value,
        中断理由詳細: pauseReasonDetail.value.trim(),
        中断時間: null,
        影響度: '中程度',
        対応状況: '対応中',
        記録者ID: 'current-user-id',
        作成日時: pauseStartTime.toISOString(),
        更新日時: pauseStartTime.toISOString()
      };

      await window.aivicApi.save(PAUSE_RECORDS_TABLE, pauseRecord);

      workStatusDiv.textContent = '中断中';
      workStatusDiv.style.background = 'rgba(255,106,0,0.2)';
      workStatusDiv.style.color = '#ff6a00';

      pauseWorkBtn.textContent = '再開';
      pauseReasonSection.style.display = 'none';
      pauseReasonSelect.value = '';
      pauseReasonDetail.value = '';

    } catch (error) {
      showError('中断記録に失敗しました');
      console.error('中断記録エラー:', error);
    }
  }

  // 中断キャンセル
  function cancelPause() {
    pauseReasonSection.style.display = 'none';
    pauseReasonSelect.value = '';
    pauseReasonDetail.value = '';
  }

  // 作業再開
  function resumeWork() {
    if (pauseStartTime) {
      totalPauseTime += new Date() - pauseStartTime;
      pauseStartTime = null;
    }

    workStatusDiv.textContent = '作業中';
    workStatusDiv.style.background = 'rgba(0,170,0,0.2)';
    workStatusDiv.style.color = '#00aa00';

    pauseWorkBtn.textContent = '中断';
  }

  // 作業終了
  async function endWork() {
    if (!currentWorkRecord) {
      showError('作業が開始されていません');
      return;
    }

    try {
      const endTime = new Date();

      if (pauseStartTime) {
        totalPauseTime += endTime - pauseStartTime;
        pauseStartTime = null;
      }

      const totalWorkTime = Math.floor((endTime - startTime - totalPauseTime) / (1000 * 60));

      const updatedRecord = {
        作業終了時刻: endTime.toISOString(),
        作業時間: totalWorkTime,
        進捗状況: '完了',
        備考: workMemoTextarea.value.trim(),
        更新日時: endTime.toISOString()
      };

      await window.aivicApi.update(WORK_RECORDS_TABLE, currentWorkRecord.id, updatedRecord);

      // 状態リセット
      currentWorkRecord = null;
      startTime = null;
      totalPauseTime = 0;
      clearInterval(elapsedTimer);

      workStatusDiv.textContent = '待機中';
      workStatusDiv.style.background = 'rgba(128,128,128,0.2)';
      workStatusDiv.style.color = 'var(--text)';
      elapsedTimeDiv.textContent = '00:00:00';

      startWorkBtn.disabled = false;
      pauseWorkBtn.disabled = true;
      pauseWorkBtn.textContent = '中断';
      endWorkBtn.disabled = true;

      await loadTodayWorkHistory();

    } catch (error) {
      showError('作業終了に失敗しました');
      console.error('作業終了エラー:', error);
    }
  }

  // 保存
  async function saveWork() {
    if (!workItemSelect.value || !workLocationInput.value.trim() || !workContentTextarea.value.trim()) {
      showError('必須項目を入力してください');
      return;
    }

    try {
      const now = new Date();
      const workRecord = {
        作業員ID: 'current-user-id',
        作業日: now.toISOString(),
        作業開始時刻: now.toISOString(),
        作業終了時刻: now.toISOString(),
        作業時間: 0,
        プロジェクト名: 'プロジェクト名',
        作業場所: workLocationInput.value.trim(),
        作業種別: workItemSelect.options[workItemSelect.selectedIndex].text.split(' - ')[1] || '',
        作業内容: workContentTextarea.value.trim(),
        進捗状況: '完了',
        備考: workMemoTextarea.value.trim(),
        承認状態: '未承認',
        承認者ID: null,
        承認日時: null,
        作成日時: now.toISOString(),
        更新日時: now.toISOString(),
        作成者ID: 'current-user-id'
      };

      const saved = await window.aivicApi.save(WORK_RECORDS_TABLE, workRecord);

      if (saved) {
        // フォームクリア
        workItemSelect.value = '';
        workLocationInput.value = '';
        workContentTextarea.value = '';
        workMemoTextarea.value = '';
        memoCountSpan.textContent = '0';

        await loadTodayWorkHistory();
      }
    } catch (error) {
      showError('保存に失敗しました');
      console.error('保存エラー:', error);
    }
  }

  // キャンセル
  function cancelWork() {
    if (currentWorkRecord || workItemSelect.value || workLocationInput.value || workContentTextarea.value || workMemoTextarea.value) {
      if (confirm('入力内容が失われますが、よろしいですか？')) {
        // フォームクリア
        workItemSelect.value = '';
        workLocationInput.value = '';
        workContentTextarea.value = '';
        workMemoTextarea.value = '';
        memoCountSpan.textContent = '0';

        // 作業中の場合は状態リセット
        if (currentWorkRecord) {
          currentWorkRecord = null;
          startTime = null;
          totalPauseTime = 0;
          pauseStartTime = null;
          clearInterval(elapsedTimer);

          workStatusDiv.textContent = '待機中';
          workStatusDiv.style.background = 'rgba(128,128,128,0.2)';
          workStatusDiv.style.color = 'var(--text)';
          elapsedTimeDiv.textContent = '00:00:00';

          startWorkBtn.disabled = false;
          pauseWorkBtn.disabled = true;
          pauseWorkBtn.textContent = '中断';
          endWorkBtn.disabled = true;
        }
      }
    }
  }

  // メモ文字数カウント
  workMemoTextarea.addEventListener('input', () => {
    memoCountSpan.textContent = workMemoTextarea.value.length;
  });

  // イベントリスナー
  startWorkBtn.addEventListener('click', startWork);
  pauseWorkBtn.addEventListener('click', () => {
    if (pauseStartTime) {
      resumeWork();
    } else {
      pauseWork();
    }
  });
  endWorkBtn.addEventListener('click', endWork);
  saveWorkBtn.addEventListener('click', saveWork);
  cancelWorkBtn.addEventListener('click', cancelWork);
  confirmPauseBtn.addEventListener('click', confirmPause);
  cancelPauseBtn.addEventListener('click', cancelPause);

  // 初期化
  updateCurrentTime();
  setInterval(updateCurrentTime, 1000);
  loadWorkItems();
  loadTodayWorkHistory();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#work-history-tbody");
  const resultCount = container.querySelector("#result-count");
  const noResults = container.querySelector("#no-results");
  const errorMessage = container.querySelector("#error-message");
  const workItemFilter = container.querySelector("#filter-work-item");

  let allRecords = [];
  let allWorkItems = [];
  let interruptCounts = {};

  // 作業項目マスタを取得してフィルターに設定
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      if (workItems) {
        allWorkItems = workItems;
        workItemFilter.innerHTML = '<option value="">すべて</option>';
        workItems.forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目名 || item.name || '';
          option.textContent = item.作業項目名 || item.name || '';
          workItemFilter.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の取得に失敗しました:', error);
    }
  }

  // 中断回数を計算
  async function loadInterruptCounts() {
    try {
      const interrupts = await window.aivicApi.list(2); // 中断記録
      if (interrupts) {
        interruptCounts = {};
        interrupts.forEach(interrupt => {
          const workRecordId = interrupt.作業記録ID || interrupt.workRecordId;
          if (workRecordId) {
            interruptCounts[workRecordId] = (interruptCounts[workRecordId] || 0) + 1;
          }
        });
      }
    } catch (error) {
      console.error('中断記録の取得に失敗しました:', error);
    }
  }

  function formatTime(timeStr) {
    if (!timeStr) return '';
    const date = new Date(timeStr);
    return date.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  function formatDate(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleDateString('ja-JP');
  }

  function formatDuration(minutes) {
    if (!minutes) return '';
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  function getStatusBadge(status) {
    const colors = {
      '完了': '#dc2626',
      '進行中': '#ea580c', 
      '中断': '#991b1b'
    };
    const color = colors[status] || '#6b7280';
    return `<span style="background: ${color}; color: #fff; padding: 2px 6px; border-radius: 4px; font-size: 11px; font-weight: 500;">${status}</span>`;
  }

  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      resultCount.textContent = '0';
      noResults.style.display = 'block';
      container.querySelector('.table-wrap').style.display = 'none';
      return;
    }

    noResults.style.display = 'none';
    container.querySelector('.table-wrap').style.display = 'block';
    resultCount.textContent = rows.length.toString();

    tbody.innerHTML = rows.map(r => {
      const workDate = formatDate(r.作業日 || r.workDate);
      const startTime = formatTime(r.作業開始時刻 || r.startTime);
      const endTime = formatTime(r.作業終了時刻 || r.endTime);
      const duration = formatDuration(r.作業時間 || r.workHours);
      const interruptCount = interruptCounts[r.作業記録ID || r.id] || 0;
      const status = r.進捗状況 || r.status || '不明';
      const workItem = r.作業種別 || r.workType || '';

      return `
        <tr data-id="${r.作業記録ID || r.id}" style="border-bottom: 1px solid var(--border); height: 36px;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workDate}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workItem}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${startTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${endTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: right;">${duration}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); text-align: right;">${interruptCount}</td>
          <td style="padding: 6px 10px; text-align: center;">${getStatusBadge(status)}</td>
          <td style="padding: 6px 10px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.作業記録ID || r.id}" style="background: transparent; color: var(--text); border: 1px solid rgba(255,255,255,0.18); padding: 4px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">詳細確認</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  function validateDateRange() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;

    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(23, 59, 59, 999);

      if (start > end) {
        showError('開始日は終了日より前の日付を入力してください');
        return false;
      }

      if (start > today || end > today) {
        showError('未来の日付は選択できません');
        return false;
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        showError('1年以上の期間は選択できません');
        return false;
      }
    }

    return true;
  }

  function filterRecords() {
    if (!validateDateRange()) {
      return;
    }

    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allRecords;

    if (startDate || endDate) {
      filtered = filtered.filter(r => {
        const workDate = new Date(r.作業日 || r.workDate);
        const start = startDate ? new Date(startDate) : null;
        const end = endDate ? new Date(endDate) : null;

        if (start && workDate < start) return false;
        if (end && workDate > end) return false;
        return true;
      });
    }

    if (workItem) {
      filtered = filtered.filter(r => 
        (r.作業種別 || r.workType || '').includes(workItem)
      );
    }

    if (status) {
      filtered = filtered.filter(r => 
        (r.進捗状況 || r.status) === status
      );
    }

    renderRows(filtered);
  }

  function resetFilters() {
    container.querySelector("#filter-start-date").value = '';
    container.querySelector("#filter-end-date").value = '';
    container.querySelector("#filter-work-item").value = '';
    container.querySelector("#filter-status").value = '';
    errorMessage.style.display = 'none';
    renderRows(allRecords);
  }

  function exportCSV() {
    const startDate = container.querySelector("#filter-start-date").value;
    const endDate = container.querySelector("#filter-end-date").value;
    const workItem = container.querySelector("#filter-work-item").value;
    const status = container.querySelector("#filter-status").value;

    let dataToExport = allRecords;

    // フィルター条件を適用
    if (startDate || endDate || workItem || status) {
      dataToExport = allRecords.filter(r => {
        let match = true;

        if (startDate || endDate) {
          const workDate = new Date(r.作業日 || r.workDate);
          const start = startDate ? new Date(startDate) : null;
          const end = endDate ? new Date(endDate) : null;
          if (start && workDate < start) match = false;
          if (end && workDate > end) match = false;
        }

        if (workItem && match) {
          match = (r.作業種別 || r.workType || '').includes(workItem);
        }

        if (status && match) {
          match = (r.進捗状況 || r.status) === status;
        }

        return match;
      });
    }

    const headers = ['作業日', '作業項目', '開始時刻', '終了時刻', '作業時間', '中断回数', '状況', 'プロジェクト名', '作業場所', '作業内容'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...dataToExport.map(r => {
        const interruptCount = interruptCounts[r.作業記録ID || r.id] || 0;
        return [
          formatDate(r.作業日 || r.workDate),
          `"${(r.作業種別 || r.workType || '').replace(/"/g, '""')}"`,
          formatTime(r.作業開始時刻 || r.startTime),
          formatTime(r.作業終了時刻 || r.endTime),
          formatDuration(r.作業時間 || r.workHours),
          interruptCount,
          `"${(r.進捗状況 || r.status || '').replace(/"/g, '""')}"`,
          `"${(r.プロジェクト名 || r.projectName || '').replace(/"/g, '""')}"`,
          `"${(r.作業場所 || r.workLocation || '').replace(/"/g, '""')}"`,
          `"${(r.作業内容 || r.workContent || '').replace(/"/g, '""')}"`
        ].join(',');
      })
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `作業履歴_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      await loadWorkItems();
      await loadInterruptCounts();

      const records = await window.aivicApi.list(1); // 作業記録
      if (records) {
        allRecords = records.sort((a, b) => {
          const dateA = new Date(a.作業日 || a.workDate);
          const dateB = new Date(b.作業日 || b.workDate);
          return dateB - dateA; // 新しい順
        });
        renderRows(allRecords);
      } else {
        allRecords = tables[1]?.records || [];
        renderRows(allRecords);
      }
    } catch (error) {
      console.error('データの読み込みに失敗しました:', error);
      allRecords = tables[1]?.records || [];
      renderRows(allRecords);
    }
  }

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", filterRecords);
  container.querySelector("#btn-reset").addEventListener("click", resetFilters);
  container.querySelector("#btn-csv-export").addEventListener("click", exportCSV);

  container.querySelector("#btn-data-extract").addEventListener("click", () => {
    window.showScreen("scr-1778907353387");
  });

  container.querySelector("#btn-back").addEventListener("click", () => {
    window.showScreen("scr-1778907133295");
  });

  // 行レベル操作
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 初期データ読み込み実行
  loadData();
}

function(container, apiUrl, tables) {
  let currentPage = 1;
  const itemsPerPage = 20;
  let allLogs = [];
  let filteredLogs = [];
  let selectedLogId = null;

  // DOM要素の取得
  const logTableBody = container.querySelector('#log-table-body');
  const resultCount = container.querySelector('#result-count');
  const pageInfo = container.querySelector('#page-info');
  const btnPrevPage = container.querySelector('#btn-prev-page');
  const btnNextPage = container.querySelector('#btn-next-page');
  const detailArea = container.querySelector('#detail-area');
  const errorMessage = container.querySelector('#error-message');
  const successMessage = container.querySelector('#success-message');
  const memoTextarea = container.querySelector('#detail-memo');
  const memoCount = container.querySelector('#memo-count');

  // メッセージ表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.style.display = 'block';
    successMessage.style.display = 'none';
    setTimeout(() => {
      errorMessage.style.display = 'none';
    }, 5000);
  }

  function showSuccess(message) {
    successMessage.textContent = message;
    successMessage.style.display = 'block';
    errorMessage.style.display = 'none';
    setTimeout(() => {
      successMessage.style.display = 'none';
    }, 3000);
  }

  // 日付フォーマット関数
  function formatDateTime(dateStr) {
    if (!dateStr) return '';
    const date = new Date(dateStr);
    return date.toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  // 重要度バッジの色を取得
  function getSeverityColor(severity) {
    switch(severity) {
      case '高': return '#dc2626';
      case '中': return '#f59e0b';
      case '低': return '#10b981';
      default: return 'var(--text-muted)';
    }
  }

  // ステータスバッジの色を取得
  function getStatusColor(status) {
    switch(status) {
      case '未確認': return '#dc2626';
      case '確認済み': return '#f59e0b';
      case '対応済み': return '#10b981';
      default: return 'var(--text-muted)';
    }
  }

  // テーブル再描画関数
  function renderRows(logs) {
    const startIndex = (currentPage - 1) * itemsPerPage;
    const endIndex = startIndex + itemsPerPage;
    const pageData = logs.slice(startIndex, endIndex);

    if (pageData.length === 0) {
      logTableBody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 20px;">該当するデータがありません</td></tr>';
    } else {
      logTableBody.innerHTML = pageData.map(log => `
        <tr data-id="${log.id}" style="cursor: pointer;" class="log-row">
          <td>${formatDateTime(log.検出日時)}</td>
          <td>${log.作業員名 || ''}</td>
          <td>${log.異常値種別 || ''}</td>
          <td>${log.検出項目 || ''}</td>
          <td>${log.検出値 || ''}</td>
          <td>${log.閾値 || ''}</td>
          <td><span style="color: ${getSeverityColor(log.重要度)}; font-weight: 500;">${log.重要度 || ''}</span></td>
          <td><span style="color: ${getStatusColor(log.確認状況)}; font-weight: 500;">${log.確認状況 || ''}</span></td>
          <td>
            <button class="action-btn secondary view-detail-btn" data-id="${log.id}" style="font-size: 12px; padding: 4px 8px;">詳細</button>
          </td>
        </tr>
      `).join('');
    }

    // 結果件数とページネーション更新
    resultCount.textContent = `${logs.length}件`;
    const totalPages = Math.ceil(logs.length / itemsPerPage);
    pageInfo.textContent = `${currentPage} / ${totalPages}`;
    btnPrevPage.disabled = currentPage <= 1;
    btnNextPage.disabled = currentPage >= totalPages;
  }

  // フィルター処理
  function applyFilters() {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const anomalyType = container.querySelector('#filter-anomaly-type').value;
    const workerName = container.querySelector('#filter-worker-name').value.toLowerCase();
    const workItem = container.querySelector('#filter-work-item').value;
    const status = container.querySelector('#filter-status').value;

    filteredLogs = allLogs.filter(log => {
      // 日付範囲フィルター
      if (startDate && log.検出日時 && new Date(log.検出日時) < new Date(startDate)) return false;
      if (endDate && log.検出日時 && new Date(log.検出日時) > new Date(endDate)) return false;

      // 異常値タイプフィルター
      if (anomalyType && log.異常値種別 !== anomalyType) return false;

      // 作業員名検索
      if (workerName && (!log.作業員名 || !log.作業員名.toLowerCase().includes(workerName))) return false;

      // 作業項目フィルター
      if (workItem && log.作業項目 !== workItem) return false;

      // ステータスフィルター
      if (status && log.確認状況 !== status) return false;

      return true;
    });

    currentPage = 1;
    renderRows(filteredLogs);
  }

  // 詳細表示
  function showDetail(logId) {
    const log = allLogs.find(l => l.id === logId);
    if (!log) return;

    selectedLogId = logId;

    container.querySelector('#detail-target-table').textContent = log.検出対象テーブル || '';
    container.querySelector('#detail-target-record').textContent = log.検出対象レコードID || '';
    container.querySelector('#detail-notification').textContent = log.通知送信フラグ ? '送信済み' : '未送信';
    container.querySelector('#detail-confirmer').textContent = log.確認者名 || '未確認';
    container.querySelector('#detail-memo').value = log.対応メモ || '';
    container.querySelector('#detail-status').value = log.確認状況 || '未確認';

    updateMemoCount();
    detailArea.style.display = 'block';
    detailArea.scrollIntoView({ behavior: 'smooth' });
  }

  // メモ文字数カウント更新
  function updateMemoCount() {
    const count = memoTextarea.value.length;
    memoCount.textContent = count;
    memoCount.style.color = count > 1000 ? '#dc2626' : 'var(--text-muted)';
  }

  // CSVエクスポート
  function exportCSV() {
    if (filteredLogs.length === 0) {
      showError('エクスポートするデータがありません');
      return;
    }

    const headers = ['検出日時', '作業員名', '異常値タイプ', '検出項目', '検出値', '閾値', '重要度', '確認状況', '対応メモ'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...filteredLogs.map(log => [
        `"${formatDateTime(log.検出日時)}"`,
        `"${log.作業員名 || ''}"`,
        `"${log.異常値種別 || ''}"`,
        `"${log.検出項目 || ''}"`,
        `"${log.検出値 || ''}"`,
        `"${log.閾値 || ''}"`,
        `"${log.重要度 || ''}"`,
        `"${log.確認状況 || ''}"`,
        `"${(log.対応メモ || '').replace(/"/g, '""')}"`
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `異常値検出ログ_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();

    showSuccess('CSVファイルをダウンロードしました');
  }

  // 初期データ読み込み
  async function loadData() {
    try {
      const logs = await window.aivicApi.list(4); // 異常値検出ログテーブル
      if (logs) {
        // 作業員名を取得してログに追加
        const users = await window.aivicApi.list(0); // ユーザーテーブル
        allLogs = logs.map(log => ({
          ...log,
          作業員名: users?.find(u => u.id === log.ユーザーID)?.氏名 || '不明'
        }));
        filteredLogs = [...allLogs];
        renderRows(filteredLogs);
      } else {
        allLogs = tables[4]?.records || [];
        filteredLogs = [...allLogs];
        renderRows(filteredLogs);
      }
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      allLogs = tables[4]?.records || [];
      filteredLogs = [...allLogs];
      renderRows(filteredLogs);
    }
  }

  // イベントリスナー設定

  // 検索ボタン
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // フィルタークリアボタン
  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-anomaly-type').value = '';
    container.querySelector('#filter-worker-name').value = '';
    container.querySelector('#filter-work-item').value = '';
    container.querySelector('#filter-status').value = '';

    filteredLogs = [...allLogs];
    currentPage = 1;
    renderRows(filteredLogs);
  });

  // エクスポートボタン
  container.querySelector('#btn-export').addEventListener('click', exportCSV);

  // ページネーション
  btnPrevPage.addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      renderRows(filteredLogs);
    }
  });

  btnNextPage.addEventListener('click', () => {
    const totalPages = Math.ceil(filteredLogs.length / itemsPerPage);
    if (currentPage < totalPages) {
      currentPage++;
      renderRows(filteredLogs);
    }
  });

  // メモ文字数カウント
  memoTextarea.addEventListener('input', updateMemoCount);

  // 対応状況更新ボタン
  container.querySelector('#btn-update-status').addEventListener('click', async () => {
    if (!selectedLogId) return;

    const memo = container.querySelector('#detail-memo').value;
    const status = container.querySelector('#detail-status').value;

    // 文字数チェック
    if (memo.length > 1000) {
      showError('コメントは1000文字以内で入力してください');
      return;
    }

    try {
      const updateData = {
        確認状況: status,
        対応メモ: memo,
        確認日時: new Date().toISOString(),
        確認者ID: 'current-user-id' // 実際の実装では現在のユーザーIDを使用
      };

      const result = await window.aivicApi.update(4, selectedLogId, updateData);
      if (result) {
        showSuccess('対応状況を更新しました');
        await loadData(); // データを再読み込み
      } else {
        showError('更新に失敗しました');
      }
    } catch (error) {
      console.error('更新エラー:', error);
      showError('ネットワークエラーが発生しました');
    }
  });

  // テーブル行クリック・詳細ボタンクリック
  container.addEventListener('click', (e) => {
    const detailBtn = e.target.closest('.view-detail-btn');
    const row = e.target.closest('.log-row');

    if (detailBtn) {
      e.stopPropagation();
      showDetail(detailBtn.dataset.id);
    } else if (row) {
      showDetail(row.dataset.id);
    }
  });

  // 初期データ読み込み
  loadData();
}

function(container, apiUrl, tables) {
  // 現在時刻の更新
  function updateCurrentTime() {
    const now = new Date();
    const timeStr = now.getFullYear() + '/' + 
                   String(now.getMonth() + 1).padStart(2, '0') + '/' + 
                   String(now.getDate()).padStart(2, '0') + ' ' + 
                   String(now.getHours()).padStart(2, '0') + ':' + 
                   String(now.getMinutes()).padStart(2, '0');
    container.querySelector('#current-datetime').textContent = timeStr;
  }

  // 初期時刻設定と1分ごとの更新
  updateCurrentTime();
  setInterval(updateCurrentTime, 60000);

  // 作業項目マスタの読み込み
  function loadWorkItems() {
    const workItemSelect = container.querySelector('#work-item-select');
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    if (workItemsTable && workItemsTable.records) {
      workItemsTable.records
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          workItemSelect.appendChild(option);
        });
    }
  }

  // 進行中・中断中作業の表示
  function renderWorkStatus() {
    window.aivicApi.list(1).then(workRecords => {
      if (!workRecords) return;

      const activeWorksContainer = container.querySelector('#active-works');
      const pausedWorksContainer = container.querySelector('#paused-works');

      const activeWorks = workRecords.filter(w => w.進捗状況 === '作業中');
      const pausedWorks = workRecords.filter(w => w.進捗状況 === '中断');

      // 進行中作業の表示
      if (activeWorks.length === 0) {
        activeWorksContainer.innerHTML = '<div class="no-data" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px; background: rgba(0,0,0,0.15); border-radius: 4px;">進行中の作業はありません</div>';
      } else {
        activeWorksContainer.innerHTML = activeWorks.map(work => {
          const startTime = new Date(work.作業開始時刻);
          const elapsed = Math.floor((Date.now() - startTime.getTime()) / 60000);
          return `
            <div style="padding: 8px 10px; margin-bottom: 6px; background: rgba(220,38,38,0.1); border: 1px solid rgba(220,38,38,0.2); border-radius: 4px;">
              <div style="font-size: 12px; font-weight: 500; color: var(--text);">${work.作業内容}</div>
              <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
                開始: ${startTime.getHours().toString().padStart(2,'0')}:${startTime.getMinutes().toString().padStart(2,'0')} | 
                経過: ${Math.floor(elapsed/60)}時間${elapsed%60}分
              </div>
            </div>
          `;
        }).join('');
      }

      // 中断中作業の表示
      if (pausedWorks.length === 0) {
        pausedWorksContainer.innerHTML = '<div class="no-data" style="padding: 12px; text-align: center; color: var(--text-muted); font-size: 12px; background: rgba(0,0,0,0.15); border-radius: 4px;">中断中の作業はありません</div>';
      } else {
        pausedWorksContainer.innerHTML = pausedWorks.map(work => {
          const startTime = new Date(work.作業開始時刻);
          return `
            <div style="padding: 8px 10px; margin-bottom: 6px; background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.1); border-radius: 4px;">
              <div style="display: flex; justify-content: space-between; align-items: center;">
                <div>
                  <div style="font-size: 12px; font-weight: 500; color: var(--text);">${work.作業内容}</div>
                  <div style="font-size: 11px; color: var(--text-muted); margin-top: 2px;">
                    開始: ${startTime.getHours().toString().padStart(2,'0')}:${startTime.getMinutes().toString().padStart(2,'0')}
                  </div>
                </div>
                <button class="action-btn resume-btn" data-id="${work.作業記録ID}" style="background: #dc2626; color: #fff; padding: 4px 8px; font-size: 11px;">再開</button>
              </div>
            </div>
          `;
        }).join('');
      }
    });
  }

  // 備考文字数カウンター
  const notesTextarea = container.querySelector('#work-notes');
  const notesCounter = container.querySelector('#notes-counter');
  notesTextarea.addEventListener('input', () => {
    notesCounter.textContent = notesTextarea.value.length;
  });

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 確認ダイアログ
  function showConfirmDialog(title, message, onConfirm) {
    const dialog = container.querySelector('#confirm-dialog');
    container.querySelector('#dialog-title').textContent = title;
    container.querySelector('#dialog-message').textContent = message;
    dialog.classList.remove('hidden');

    const confirmBtn = container.querySelector('#dialog-confirm');
    const cancelBtn = container.querySelector('#dialog-cancel');

    const handleConfirm = () => {
      dialog.classList.add('hidden');
      onConfirm();
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    const handleCancel = () => {
      dialog.classList.add('hidden');
      confirmBtn.removeEventListener('click', handleConfirm);
      cancelBtn.removeEventListener('click', handleCancel);
    };

    confirmBtn.addEventListener('click', handleConfirm);
    cancelBtn.addEventListener('click', handleCancel);
  }

  // 作業開始フォーム送信
  container.querySelector('#work-start-form').addEventListener('submit', async (e) => {
    e.preventDefault();

    const workItemId = container.querySelector('#work-item-select').value;
    const workLocation = container.querySelector('#work-location').value.trim();
    const workNotes = container.querySelector('#work-notes').value.trim();

    // バリデーション
    if (!workItemId) {
      showError('作業項目を選択してください');
      return;
    }

    // 進行中作業の重複チェック
    const activeWorks = await window.aivicApi.list(1);
    if (activeWorks && activeWorks.some(w => w.進捗状況 === '作業中')) {
      showError('既に実行中の作業があります。同時に複数の作業を開始することはできません。');
      return;
    }

    // 作業項目名の取得
    const workItemsTable = tables.find(t => t.tableName === '作業項目マスタ');
    const workItem = workItemsTable?.records?.find(item => item.作業項目ID === workItemId);

    const workRecord = {
      作業員ID: 'current-user-id', // 実際の実装では認証情報から取得
      作業日: new Date().toISOString().split('T')[0],
      作業開始時刻: new Date().toISOString(),
      作業終了時刻: null,
      作業時間: null,
      プロジェクト名: workItem?.作業項目名 || '',
      作業場所: workLocation,
      作業種別: workItem?.カテゴリ || '',
      作業内容: workItem?.作業項目名|| '',
      進捗状況: '作業中',
      備考: workNotes,
      承認状態: '未承認',
      承認者ID: null,
      承認日時: null,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'current-user-id'
    };

    const saved = await window.aivicApi.save(1, workRecord);
    if (saved) {
      // フォームクリア
      container.querySelector('#work-start-form').reset();
      container.querySelector('#notes-counter').textContent = '0';

      // 作業状況を更新
      renderWorkStatus();

      // 成功メッセージ（簡易的にアラート）
      alert('作業記録を開始しました');
    }
  });

  // フォームクリアボタン
  container.querySelector('#btn-clear-form').addEventListener('click', () => {
    container.querySelector('#work-start-form').reset();
    container.querySelector('#notes-counter').textContent = '0';
    container.querySelector('#error-message').classList.add('hidden');
  });

  // 作業再開ボタン
  container.addEventListener('click', async (e) => {
    const resumeBtn = e.target.closest('.resume-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.id;

      showConfirmDialog(
        '作業再開確認',
        '中断中の作業を再開しますか？',
        async () => {
          const updated = await window.aivicApi.update(1, workId, {
            進捗状況: '作業中',
            更新日時: new Date().toISOString()
          });

          if (updated) {
            renderWorkStatus();
            alert('作業を再開しました');
          }
        }
      );
    }
  });

  // 設定ボタン
  container.querySelector('#btn-settings').addEventListener('click', () => {
    alert('設定画面は未実装です');
  });

  // ログアウトボタン
  container.querySelector('#btn-logout').addEventListener('click', () => {
    showConfirmDialog(
      'ログアウト確認',
      'ログアウトしますか？',
      () => {
        window.location.href = './login.html';
      }
    );
  });

  // 工数入力画面への遷移
  container.querySelector('#btn-work-hour-input').addEventListener('click', () => {
    window.showScreen("scr-1778907296658");
  });

  // 初期データ読み込み
  loadWorkItems();
  renderWorkStatus();
}

function(container, apiUrl, tables) {
  // 現在の作業記録データ（実際の実装では前画面から渡される）
  let currentWorkRecord = {
    id: 'wr-001',
    workItemName: '配管設置作業 - A棟3階',
    startTime: '09:00',
    endTime: '17:30',
    totalMinutes: 510, // 8時間30分
    breakMinutes: 60,   // 1時間
    actualMinutes: 450  // 7時間30分
  };

  // 時刻情報の表示更新
  function updateTimeDisplay() {
    container.querySelector('#start-time').textContent = currentWorkRecord.startTime;
    container.querySelector('#end-time').textContent = currentWorkRecord.endTime;
    container.querySelector('#total-time').textContent = formatMinutes(currentWorkRecord.totalMinutes);
    container.querySelector('#break-time').textContent = formatMinutes(currentWorkRecord.breakMinutes);
    container.querySelector('#actual-work-time').textContent = formatMinutes(currentWorkRecord.actualMinutes);
    container.querySelector('#work-item').textContent = currentWorkRecord.workItemName;
  }

  // 分を時:分形式に変換
  function formatMinutes(minutes) {
    const hours = Math.floor(minutes / 60);
    const mins = minutes % 60;
    return `${hours}:${mins.toString().padStart(2, '0')}`;
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // バリデーション
  function validateForm() {
    hideError();

    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueContent = container.querySelector('#issue-content').value.trim();
    const workMemo = container.querySelector('#work-memo').value.trim();

    if (!completionStatus) {
      showError('完了状況を選択してください。');
      return false;
    }

    if (hasIssue && !issueContent) {
      showError('異常・問題報告にチェックを入れた場合は、異常内容を入力してください。');
      return false;
    }

    if (workMemo.length > 1000) {
      showError('作業メモは1000文字以内で入力してください。');
      return false;
    }

    if (issueContent.length > 500) {
      showError('異常内容は500文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 文字数カウンター更新
  function updateCharCount(textareaId, countId) {
    const textarea = container.querySelector(`#${textareaId}`);
    const counter = container.querySelector(`#${countId}`);
    if (textarea && counter) {
      counter.textContent = textarea.value.length;
    }
  }

  // 初期表示
  updateTimeDisplay();

  // 異常報告チェックボックスの制御
  container.querySelector('#has-issue').addEventListener('change', function() {
    const issueSection = container.querySelector('#issue-content-section');
    const issueContent = container.querySelector('#issue-content');

    if (this.checked) {
      issueSection.classList.remove('hidden');
    } else {
      issueSection.classList.add('hidden');
      issueContent.value = '';
      updateCharCount('issue-content', 'issue-count');
    }
  });

  // 文字数カウンター
  container.querySelector('#work-memo').addEventListener('input', function() {
    updateCharCount('work-memo', 'memo-count');
  });

  container.querySelector('#issue-content').addEventListener('input', function() {
    updateCharCount('issue-content', 'issue-count');
  });

  // 記録確定ボタン
  container.querySelector('#btn-confirm').addEventListener('click', async function() {
    if (!validateForm()) return;

    const workMemo = container.querySelector('#work-memo').value.trim();
    const completionStatus = container.querySelector('#completion-status').value;
    const hasIssue = container.querySelector('#has-issue').checked;
    const issueContent = container.querySelector('#issue-content').value.trim();

    const workRecordData = {
      id: currentWorkRecord.id,
      workEndTime: new Date().toISOString(),
      workTime: currentWorkRecord.actualMinutes,
      projectName: '配管設置プロジェクト',
      workLocation: 'A棟3階',
      workType: '設置作業',
      workContent: workMemo || '作業完了',
      progressStatus: completionStatus,
      remarks: workMemo,
      approvalStatus: '未承認',
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      createdBy: 'current-user-id'
    };

    try {
      // 作業記録の更新
      const updated = await window.aivicApi.update(1, currentWorkRecord.id, workRecordData);

      if (updated) {
        // 異常報告がある場合は異常値検出ログに記録
        if (hasIssue && issueContent) {
          const anomalyData = {
            detectionTargetTable: '作業記録',
            detectionTargetRecordId: currentWorkRecord.id,
            userId: 'current-user-id',
            anomalyType: '作業異常報告',
            detectionItem: '作業内容',
            detectionValue: issueContent,
            threshold: '正常範囲',
            severity: '中',
            confirmationStatus: '未確認',
            notificationSent: true,
            detectionDateTime: new Date().toISOString(),
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
          };

          await window.aivicApi.save(4, anomalyData);
        }

        alert('工数記録が正常に確定されました。');
        // 前画面に戻るか、一覧画面に遷移
        window.history.back();
      } else {
        showError('記録の保存に失敗しました。再度お試しください。');
      }
    } catch (error) {
      showError('システムエラーが発生しました。管理者にお問い合わせください。');
      console.error('Save error:', error);
    }
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('入力内容が破棄されますが、よろしいですか？')) {
      window.history.back();
    }
  });

  // 記録確認ボタン
  container.querySelector('#btn-check-record').addEventListener('click', function() {
    window.showScreen("scr-1778907226171");
  });

  // フォーカス時のスタイル適用
  const inputs = container.querySelectorAll('input, select, textarea');
  inputs.forEach(input => {
    input.addEventListener('focus', function() {
      this.style.outline = 'none';
      this.style.borderColor = 'var(--primary)';
      this.style.boxShadow = '0 0 0 2px rgba(255,255,255,0.08)';
    });

    input.addEventListener('blur', function() {
      this.style.borderColor = 'rgba(255,255,255,0.18)';
      this.style.boxShadow = 'none';
    });
  });

  // ボタンホバー効果
  const primaryBtn = container.querySelector('#btn-confirm');
  primaryBtn.addEventListener('mouseenter', function() {
    this.style.background = 'var(--primary-hover)';
  });
  primaryBtn.addEventListener('mouseleave', function() {
    this.style.background = 'var(--primary)';
  });

  const secondaryBtns = container.querySelectorAll('.action-btn.secondary');
  secondaryBtns.forEach(btn => {
    btn.addEventListener('mouseenter', function() {
      this.style.background = 'rgba(255,255,255,0.05)';
    });
    btn.addEventListener('mouseleave', function() {
      this.style.background = 'transparent';
    });
  });
}

function(container, apiUrl, tables) {
  let autoSaveInterval = null;
  let currentSaveInterval = 30;
  let localDataCache = [];
  let syncPendingCount = 0;
  let isOnline = navigator.onLine;

  // DOM要素の取得
  const autoSaveStatus = container.querySelector('#auto-save-status');
  const lastSaveTime = container.querySelector('#last-save-time');
  const networkStatus = container.querySelector('#network-status');
  const syncPendingCountEl = container.querySelector('#sync-pending-count');
  const localDataCount = container.querySelector('#local-data-count');
  const saveIntervalInput = container.querySelector('#save-interval');
  const errorNotification = container.querySelector('#error-notification');
  const errorMessage = container.querySelector('#error-message');
  const localDataSection = container.querySelector('#local-data-section');
  const localDataTbody = container.querySelector('#local-data-tbody');
  const recoverySection = container.querySelector('#recovery-section');

  // ローカルストレージキー
  const STORAGE_KEYS = {
    WORK_RECORDS: 'workRecords_local',
    SAVE_INTERVAL: 'autoSaveInterval',
    LAST_SAVE_TIME: 'lastSaveTime',
    RECOVERY_DATA: 'recoveryData'
  };

  // 初期化
  function init() {
    loadSettings();
    updateNetworkStatus();
    loadLocalData();
    checkRecoveryData();
    startAutoSave();

    // ネットワーク状態の監視
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
  }

  // 設定の読み込み
  function loadSettings() {
    const savedInterval = localStorage.getItem(STORAGE_KEYS.SAVE_INTERVAL);
    if (savedInterval) {
      currentSaveInterval = parseInt(savedInterval);
      saveIntervalInput.value = currentSaveInterval;
    }

    const lastSave = localStorage.getItem(STORAGE_KEYS.LAST_SAVE_TIME);
    if (lastSave) {
      lastSaveTime.textContent = `最終保存: ${new Date(lastSave).toLocaleString()}`;
    }
  }

  // ネットワーク状態の更新
  function updateNetworkStatus() {
    if (isOnline) {
      networkStatus.textContent = 'オンライン';
      networkStatus.style.color = '#059669';
    } else {
      networkStatus.textContent = 'オフライン';
      networkStatus.style.color = '#dc2626';
    }
    syncPendingCountEl.textContent = `同期待ち: ${syncPendingCount}件`;
  }

  // ローカルデータの読み込み
  function loadLocalData() {
    try {
      const data = localStorage.getItem(STORAGE_KEYS.WORK_RECORDS);
      localDataCache = data ? JSON.parse(data) : [];
      localDataCount.textContent = `${localDataCache.length}件`;

      // 同期待ち件数の計算
      syncPendingCount = localDataCache.filter(record => !record.synced).length;
      updateNetworkStatus();
    } catch (error) {
      console.error('ローカルデータの読み込みエラー:', error);
      localDataCache = [];
      localDataCount.textContent = '0件';
    }
  }

  // 復旧データのチェック
  function checkRecoveryData() {
    const recoveryData = localStorage.getItem(STORAGE_KEYS.RECOVERY_DATA);
    if (recoveryData) {
      recoverySection.style.display = 'block';
    }
  }

  // 自動保存の開始
  function startAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
    }

    autoSaveInterval = setInterval(performAutoSave, currentSaveInterval * 1000);
    autoSaveStatus.textContent = '動作中';
    autoSaveStatus.style.color = '#059669';
  }

  // 自動保存の停止
  function stopAutoSave() {
    if (autoSaveInterval) {
      clearInterval(autoSaveInterval);
      autoSaveInterval = null;
    }
    autoSaveStatus.textContent = '停止中';
    autoSaveStatus.style.color = '#dc2626';
  }

  // 自動保存の実行
  async function performAutoSave() {
    try {
      // 現在の入力データを取得（実際の実装では工数記録画面からデータを取得）
      const currentData = getCurrentWorkData();

      if (currentData && Object.keys(currentData).length > 0) {
        await saveWorkRecord(currentData);

        const now = new Date().toISOString();
        localStorage.setItem(STORAGE_KEYS.LAST_SAVE_TIME, now);
        lastSaveTime.textContent = `最終保存: ${new Date(now).toLocaleString()}`;

        hideError();
      }
    } catch (error) {
      console.error('自動保存エラー:', error);
      showError('自動保存に失敗しました: ' + error.message);
    }
  }

  // 現在の作業データを取得（モック）
  function getCurrentWorkData() {
    // 実際の実装では工数記録画面から現在の入力値を取得
    const mockData = {
      workDate: new Date().toISOString().split('T')[0],
      startTime: new Date().toISOString(),
      projectName: 'サンプルプロジェクト',
      workLocation: 'A現場',
      workType: '点検作業',
      workContent: '定期点検実施',
      progress: '作業中'
    };

    // データが空でない場合のみ返す
    return Math.random() > 0.7 ? mockData : null;
  }

  // 作業記録の保存
  async function saveWorkRecord(data) {
    const record = {
      id: 'local_' + Date.now(),
      ...data,
      createdAt: new Date().toISOString(),
      synced: false
    };

    // ローカルストレージに保存
    localDataCache.push(record);
    localStorage.setItem(STORAGE_KEYS.WORK_RECORDS, JSON.stringify(localDataCache));

    // オンラインの場合はサーバーにも保存を試行
    if (isOnline) {
      try {
        const saved = await window.aivicApi.save(1, {
          作業員ID: 'current_user_id',
          作業日: data.workDate,
          作業開始時刻: data.startTime,
          プロジェクト名: data.projectName,
          作業場所: data.workLocation,
          作業種別: data.workType,
          作業内容: data.workContent,
          進捗状況: data.progress,
          承認状態: '未承認',
          作成者ID: 'current_user_id'
        });

        if (saved) {
          record.synced = true;
          record.serverId = saved.id;
          localStorage.setItem(STORAGE_KEYS.WORK_RECORDS, JSON.stringify(localDataCache));
        }
      } catch (error) {
        console.error('サーバー保存エラー:', error);
        // ローカル保存は成功しているのでエラーは表示しない
      }
    }

    loadLocalData();
  }

  // 手動同期の実行
  async function performManualSync() {
    const unsyncedRecords = localDataCache.filter(record => !record.synced);

    if (unsyncedRecords.length === 0) {
      alert('同期待ちのデータはありません。');
      return;
    }

    if (!isOnline) {
      showError('オフライン状態のため同期できません。');
      return;
    }

    let successCount = 0;
    let failCount = 0;

    for (const record of unsyncedRecords) {
      try {
        const saved = await window.aivicApi.save(1, {
          作業員ID: 'current_user_id',
          作業日: record.workDate,
          作業開始時刻: record.startTime,
          プロジェクト名: record.projectName,
          作業場所: record.workLocation,
          作業種別: record.workType,
          作業内容: record.workContent,
          進捗状況: record.progress,
          承認状態: '未承認',
          作成者ID: 'current_user_id'
        });

        if (saved) {
          record.synced = true;
          record.serverId = saved.id;
          successCount++;
        } else {
          failCount++;
        }
      } catch (error) {
        console.error('同期エラー:', error);
        failCount++;
      }
    }

    localStorage.setItem(STORAGE_KEYS.WORK_RECORDS, JSON.stringify(localDataCache));
    loadLocalData();

    if (failCount === 0) {
      alert(`${successCount}件のデータを同期しました。`);
      hideError();
    } else {
      showError(`${successCount}件同期成功、${failCount}件失敗しました。`);
    }
  }

  // ローカルデータ一覧の表示
  function renderLocalData() {
    localDataTbody.innerHTML = localDataCache.map(record => `
      <tr data-id="${record.id}">
        <td style="padding: 6px 10px;">${new Date(record.createdAt).toLocaleString()}</td>
        <td style="padding: 6px 10px;">${record.workContent || '--'}</td>
        <td style="padding: 6px 10px;">
          <span style="color: ${record.synced ? '#059669' : '#f59e0b'};">
            ${record.synced ? '同期済み' : '未同期'}
          </span>
        </td>
        <td style="padding: 6px 10px;">
          <button class="action-btn secondary delete-local-btn" data-id="${record.id}" style="font-size: 11px; padding: 4px 8px;">削除</button>
        </td>
      </tr>
    `).join('');
  }

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorNotification.style.display = 'block';
  }

  // エラー非表示
  function hideError() {
    errorNotification.style.display = 'none';
  }

  // ネットワーク接続時の処理
  function handleOnline() {
    isOnline = true;
    updateNetworkStatus();

    // 自動同期を実行
    setTimeout(() => {
      performManualSync();
    }, 1000);
  }

  // ネットワーク切断時の処理
  function handleOffline() {
    isOnline = false;
    updateNetworkStatus();
  }

  // イベントリスナーの設定
  container.querySelector('#btn-save-settings').addEventListener('click', () => {
    const newInterval = parseInt(saveIntervalInput.value);

    if (newInterval < 1) {
      showError('保存間隔は1秒以上で設定してください。');
      return;
    }

    if (newInterval > 86400) {
      showError('保存間隔は86400秒以下で設定してください。');
      return;
    }

    currentSaveInterval = newInterval;
    localStorage.setItem(STORAGE_KEYS.SAVE_INTERVAL, currentSaveInterval.toString());

    // 自動保存を再開
    startAutoSave();

    alert('保存間隔を更新しました。');
    hideError();
  });

  container.querySelector('#btn-manual-sync').addEventListener('click', performManualSync);

  container.querySelector('#btn-view-local').addEventListener('click', () => {
    renderLocalData();
    localDataSection.style.display = 'block';
  });

  container.querySelector('#btn-hide-local').addEventListener('click', () => {
    localDataSection.style.display = 'none';
  });

  container.querySelector('#btn-retry').addEventListener('click', performAutoSave);

  container.querySelector('#btn-recover-data').addEventListener('click', () => {
    const recoveryData = localStorage.getItem(STORAGE_KEYS.RECOVERY_DATA);
    if (recoveryData) {
      // 復旧データを工数記録画面に渡す（実際の実装では画面間でデータを受け渡し）
      localStorage.removeItem(STORAGE_KEYS.RECOVERY_DATA);
      recoverySection.style.display = 'none';
      alert('データを復旧しました。工数記録画面で確認してください。');
      window.showScreen('scr-1778907133295');
    }
  });

  container.querySelector('#btn-discard-data').addEventListener('click', () => {
    if (confirm('復旧データを破棄しますか？この操作は取り消せません。')) {
      localStorage.removeItem(STORAGE_KEYS.RECOVERY_DATA);
      recoverySection.style.display = 'none';
    }
  });

  // ローカルデータの削除
  container.addEventListener('click', (e) => {
    const deleteBtn = e.target.closest('.delete-local-btn');
    if (deleteBtn) {
      const recordId = deleteBtn.dataset.id;
      if (confirm('このローカルデータを削除しますか？')) {
        localDataCache = localDataCache.filter(record => record.id !== recordId);
        localStorage.setItem(STORAGE_KEYS.WORK_RECORDS, JSON.stringify(localDataCache));
        loadLocalData();
        renderLocalData();
      }
    }
  });

  // 初期化実行
  init();
}

function(container, apiUrl, tables) {
  let mediaRecorder = null;
  let audioChunks = [];
  let recordedBlob = null;
  let isRecording = false;

  // DOM要素の取得
  const form = container.querySelector('#interruption-form');
  const startTimeInput = container.querySelector('#start-time');
  const reasonSelect = container.querySelector('#interruption-reason');
  const detailsTextarea = container.querySelector('#interruption-details');
  const locationInput = container.querySelector('#interruption-location');
  const relatedWorkSelect = container.querySelector('#related-work');
  const durationDiv = container.querySelector('#interruption-duration');
  const charCountSpan = container.querySelector('#char-count');
  const photoUpload = container.querySelector('#photo-upload');
  const photoBtn = container.querySelector('#photo-btn');
  const photoPreview = container.querySelector('#photo-preview');
  const recordBtn = container.querySelector('#record-btn');
  const playBtn = container.querySelector('#play-btn');
  const recordingStatus = container.querySelector('#recording-status');
  const selectAllImpact = container.querySelector('#select-all-impact');
  const impactCheckboxes = container.querySelectorAll('input[name="impact"]');
  const tempSaveBtn = container.querySelector('#temp-save-btn');
  const completeBtn = container.querySelector('#complete-btn');
  const errorMessage = container.querySelector('#error-message');

  // 現在時刻を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  startTimeInput.value = now.toISOString().slice(0, 16);

  // 関連作業項目の読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      if (workItems) {
        relatedWorkSelect.innerHTML = '<option value="">選択してください</option>';
        workItems.forEach(item => {
          const option = document.createElement('option');
          option.value = item.作業項目ID;
          option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
          relatedWorkSelect.appendChild(option);
        });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // 文字数カウント
  detailsTextarea.addEventListener('input', () => {
    const count = detailsTextarea.value.length;
    charCountSpan.textContent = count;
    if (count > 1000) {
      charCountSpan.style.color = '#dc2626';
    } else {
      charCountSpan.style.color = 'var(--text-muted)';
    }
  });

  // 中断時間の自動計算
  function updateDuration() {
    const startTime = startTimeInput.value;
    if (startTime) {
      const start = new Date(startTime);
      const now = new Date();
      const diffMs = now - start;
      if (diffMs > 0) {
        const hours = Math.floor(diffMs / (1000 * 60 * 60));
        const minutes = Math.floor((diffMs % (1000 * 60 * 60)) / (1000 * 60));
        durationDiv.textContent = `${hours}時間${minutes}分`;
        durationDiv.style.color = 'var(--text)';
      } else {
        durationDiv.textContent = '未来の時刻は設定できません';
        durationDiv.style.color = '#dc2626';
      }
    } else {
      durationDiv.textContent = '自動計算されます';
      durationDiv.style.color = 'var(--text-muted)';
    }
  }

  startTimeInput.addEventListener('change', updateDuration);
  setInterval(updateDuration, 60000); // 1分ごとに更新

  // 写真アップロード
  photoBtn.addEventListener('click', () => {
    photoUpload.click();
  });

  photoUpload.addEventListener('change', (e) => {
    const files = Array.from(e.target.files);
    photoPreview.innerHTML = '';

    files.forEach((file, index) => {
      if (!file.type.startsWith('image/')) {
        showError('画像ファイルのみアップロード可能です');
        return;
      }

      if (file.size > 10 * 1024 * 1024) { // 10MB
        showError('ファイルサイズは10MB以下にしてください');
        return;
      }

      const reader = new FileReader();
      reader.onload = (e) => {
        const img = document.createElement('img');
        img.src = e.target.result;
        img.style.cssText = 'width: 60px; height: 60px; object-fit: cover; border-radius: 4px; border: 1px solid rgba(255,255,255,0.18);';
        photoPreview.appendChild(img);
      };
      reader.readAsDataURL(file);
    });
  });

  // 音声録音
  recordBtn.addEventListener('click', async () => {
    if (!isRecording) {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        mediaRecorder = new MediaRecorder(stream);
        audioChunks = [];

        mediaRecorder.ondataavailable = (event) => {
          audioChunks.push(event.data);
        };

        mediaRecorder.onstop = () => {
          recordedBlob = new Blob(audioChunks, { type: 'audio/wav' });
          playBtn.disabled = false;
          playBtn.style.cursor = 'pointer';
          playBtn.style.color = 'var(--text)';
          recordingStatus.textContent = '録音完了';
        };

        mediaRecorder.start();
        isRecording = true;
        recordBtn.textContent = '🛑 録音停止';
        recordBtn.style.background = 'rgba(220, 38, 38, 0.2)';
        recordingStatus.textContent = '録音中...';

      } catch (error) {
        showError('マイクへのアクセスが拒否されました');
      }
    } else {
      mediaRecorder.stop();
      mediaRecorder.stream.getTracks().forEach(track => track.stop());
      isRecording = false;
      recordBtn.textContent = '🎤 録音開始';
      recordBtn.style.background = 'transparent';
    }
  });

  playBtn.addEventListener('click', () => {
    if (recordedBlob) {
      const audio = new Audio(URL.createObjectURL(recordedBlob));
      audio.play();
    }
  });

  // 影響範囲の全選択・全解除
  selectAllImpact.addEventListener('change', () => {
    impactCheckboxes.forEach(checkbox => {
      checkbox.checked = selectAllImpact.checked;
    });
  });

  impactCheckboxes.forEach(checkbox => {
    checkbox.addEventListener('change', () => {
      const checkedCount = Array.from(impactCheckboxes).filter(cb => cb.checked).length;
      selectAllImpact.checked = checkedCount === impactCheckboxes.length;
      selectAllImpact.indeterminate = checkedCount > 0 && checkedCount < impactCheckboxes.length;
    });
  });

  // エラー表示
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove('hidden');
    setTimeout(() => {
      errorMessage.classList.add('hidden');
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const startTime = startTimeInput.value;
    const reason = reasonSelect.value;
    const urgency = container.querySelector('input[name="urgency"]:checked');

    if (!startTime) {
      showError('中断開始時刻は必須です');
      return false;
    }

    if (!reason) {
      showError('中断理由は必須です');
      return false;
    }

    if (!urgency) {
      showError('緊急度は必須です');
      return false;
    }

    const startDate = new Date(startTime);
    const now = new Date();
    if (startDate > now) {
      showError('未来の時刻は設定できません');
      return false;
    }

    const detailsLength = detailsTextarea.value.length;
    if (detailsLength > 1000) {
      showError('中断詳細は1000文字以内で入力してください');
      return false;
    }

    return true;
  }

  // フォームデータ収集
  function collectFormData() {
    const urgency = container.querySelector('input[name="urgency"]:checked');
    const impactRanges = Array.from(container.querySelectorAll('input[name="impact"]:checked'))
      .map(cb => cb.value);

    return {
      中断記録ID: crypto.randomUUID(),
      作業記録ID: null, // 実際の実装では現在の作業記録IDを設定
      中断開始日時: new Date(startTimeInput.value).toISOString(),
      中断終了日時: null,
      中断理由区分: reasonSelect.value,
      中断理由詳細: detailsTextarea.value,
      中断時間: null,
      影響度: urgency ? urgency.value : null,
      対応状況: '対応中',
      記録者ID: 'current-user-id', // 実際の実装では現在のユーザーIDを設定
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      中断場所: locationInput.value,
      関連作業項目: relatedWorkSelect.value,
      影響範囲: impactRanges.join(','),
      写真添付: photoUpload.files.length > 0,
      音声メモ: recordedBlob !== null
    };
  }

  // 一時保存
  tempSaveBtn.addEventListener('click', () => {
    const formData = collectFormData();
    localStorage.setItem('interruption_temp_data', JSON.stringify(formData));

    const tempMessage = document.createElement('div');
    tempMessage.textContent = '一時保存しました';
    tempMessage.style.cssText = 'background: rgba(34, 197, 94, 0.1); border: 1px solid rgba(34, 197, 94, 0.3); color: #22c55e; padding: 8px 12px; border-radius: 6px; font-size: 13px; margin-bottom: 12px;';
    errorMessage.parentNode.insertBefore(tempMessage, errorMessage);

    setTimeout(() => {
      tempMessage.remove();
    }, 3000);
  });

  // 一時保存データの復元
  function restoreTempData() {
    const tempData = localStorage.getItem('interruption_temp_data');
    if (tempData) {
      try {
        const data = JSON.parse(tempData);
        if (data.中断開始日時) {
          const date = new Date(data.中断開始日時);
          date.setMinutes(date.getMinutes() - date.getTimezoneOffset());
          startTimeInput.value = date.toISOString().slice(0, 16);
        }
        if (data.中断理由区分) reasonSelect.value = data.中断理由区分;
        if (data.中断理由詳細) detailsTextarea.value = data.中断理由詳細;
        if (data.中断場所) locationInput.value = data.中断場所;
        if (data.関連作業項目) relatedWorkSelect.value = data.関連作業項目;
        if (data.影響度) {
          const urgencyRadio = container.querySelector(`input[name="urgency"][value="${data.影響度}"]`);
          if (urgencyRadio) urgencyRadio.checked = true;
        }
        if (data.影響範囲) {
          const ranges = data.影響範囲.split(',');
          ranges.forEach(range => {
            const checkbox = container.querySelector(`input[name="impact"][value="${range}"]`);
            if (checkbox) checkbox.checked = true;
          });
        }

        // 文字数更新
        charCountSpan.textContent = detailsTextarea.value.length;
        updateDuration();
      } catch (error) {
        console.error('一時保存データの復元に失敗しました:', error);
      }
    }
  }

  // 記録完了
  completeBtn.addEventListener('click', async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    try {
      const formData = collectFormData();
      const saved = await window.aivicApi.save(2, formData); // 中断記録テーブル

      if (saved) {
        // 一時保存データを削除
        localStorage.removeItem('interruption_temp_data');

        // 成功メッセージ
        const successMessage = document.createElement('div');
        successMessage.textContent = '中断記録を保存しました';
        successMessage.style.cssText = 'background: rgba(34, 197, 94, 0.1); border: 1px solid rgba(34, 197, 94, 0.3); color: #22c55e; padding: 8px 12px; border-radius: 6px; font-size: 13px; margin-bottom: 12px;';
        errorMessage.parentNode.insertBefore(successMessage, errorMessage);

        setTimeout(() => {
          window.showScreen("scr-1778907251446"); // 作業再開記録画面
        }, 1500);
      } else {
        showError('保存に失敗しました。ネットワーク接続を確認してください。');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      showError('保存中にエラーが発生しました。');
    }
  });

  // 初期化
  loadWorkItems();
  restoreTempData();
  updateDuration();
}

function(container, apiUrl, tables) {
  let selectedWorkRecord = null;
  let selectedInterruptRecord = null;

  // DOM要素の取得
  const suspendedWorkTbody = container.querySelector('#suspended-work-tbody');
  const noSuspendedWork = container.querySelector('#no-suspended-work');
  const resumeForm = container.querySelector('#resume-form');
  const resumeTime = container.querySelector('#resume-time');
  const resumeReasonSelect = container.querySelector('#resume-reason-select');
  const resumeReasonDetail = container.querySelector('#resume-reason-detail');
  const charCount = container.querySelector('#char-count');
  const resumeReasonError = container.querySelector('#resume-reason-error');
  const confirmDialog = container.querySelector('#resume-confirm-dialog');

  // 現在時刻を再開時刻に設定
  function setCurrentTime() {
    const now = new Date();
    const localDateTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 16);
    resumeTime.value = localDateTime;
  }

  // 中断中作業一覧の描画
  function renderSuspendedWorks(workRecords, interruptRecords) {
    // 中断中の作業記録を抽出（進捗状況が「中断」のもの）
    const suspendedWorks = workRecords.filter(work => work.進捗状況 === '中断');

    if (suspendedWorks.length === 0) {
      suspendedWorkTbody.innerHTML = '';
      noSuspendedWork.classList.remove('hidden');
      return;
    }

    noSuspendedWork.classList.add('hidden');

    suspendedWorkTbody.innerHTML = suspendedWorks.map(work => {
      // 対応する中断記録を検索
      const interrupt = interruptRecords.find(int => int.作業記録ID === work.作業記録ID && !int.中断終了日時);
      const suspendTime = interrupt ? new Date(interrupt.中断開始日時).toLocaleString() : '-';
      const suspendReason = interrupt ? interrupt.中断理由詳細 || interrupt.中断理由区分 : '-';

      return `
        <tr data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt?.中断記録ID || ''}" style="cursor: pointer;">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${work.作業内容 || work.プロジェクト名}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${suspendTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.05);">${suspendReason}</td>
          <td style="padding: 6px 10px; border-bottom: 1px solid rgba(255,255,255,0.05);">
            <button class="action-btn resume-work-btn" data-work-id="${work.作業記録ID}" data-interrupt-id="${interrupt?.中断記録ID || ''}" 
                    style="background: #dc2626; color: #fff; font-size: 12px; padding: 4px 8px;">再開</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 選択された作業情報の表示
  function showSelectedWorkInfo(workRecord, interruptRecord) {
    container.querySelector('#selected-work-name').textContent = workRecord.作業内容 || workRecord.プロジェクト名;

    if (interruptRecord) {
      container.querySelector('#selected-suspend-time').textContent = new Date(interruptRecord.中断開始日時).toLocaleString();
      container.querySelector('#selected-suspend-reason').textContent = interruptRecord.中断理由詳細 || interruptRecord.中断理由区分;
    }

    setCurrentTime();
    resumeForm.classList.remove('hidden');
  }

  // 文字数カウント更新
  function updateCharCount() {
    const count = resumeReasonDetail.value.length;
    charCount.textContent = count;

    if (count > 500) {
      charCount.style.color = '#dc2626';
      resumeReasonError.textContent = '再開理由は500文字以内で入力してください';
      resumeReasonError.classList.remove('hidden');
    } else {
      charCount.style.color = 'var(--text-muted)';
      resumeReasonError.classList.add('hidden');
    }
  }

  // バリデーション
  function validateForm() {
    let isValid = true;

    if (!resumeReasonDetail.value.trim()) {
      resumeReasonError.textContent = '再開理由の入力は必須です';
      resumeReasonError.classList.remove('hidden');
      isValid = false;
    } else if (resumeReasonDetail.value.length > 500) {
      resumeReasonError.textContent = '再開理由は500文字以内で入力してください';
      resumeReasonError.classList.remove('hidden');
      isValid = false;
    } else {
      resumeReasonError.classList.add('hidden');
    }

    return isValid;
  }

  // 作業再開処理
  async function resumeWork() {
    if (!validateForm()) return;

    try {
      // 作業記録の更新（進捗状況を「作業中」に変更）
      const updatedWork = await window.aivicApi.update(1, selectedWorkRecord.作業記録ID, {
        進捗状況: '作業中',
        更新日時: new Date().toISOString()
      });

      if (!updatedWork) {
        alert('作業記録の更新に失敗しました');
        return;
      }

      // 中断記録の更新（中断終了日時を設定）
      if (selectedInterruptRecord) {
        await window.aivicApi.update(2, selectedInterruptRecord.中断記録ID, {
          中断終了日時: resumeTime.value,
          中断時間: Math.floor((new Date(resumeTime.value) - new Date(selectedInterruptRecord.中断開始日時)) / (1000 * 60)),
          対応状況: '解決済み',
          更新日時: new Date().toISOString()
        });
      }

      // 新しい中断記録として再開記録を作成（再開理由を記録）
      const resumeReason = resumeReasonSelect.value || 'その他';
      await window.aivicApi.save(2, {
        作業記録ID: selectedWorkRecord.作業記録ID,
        中断開始日時: resumeTime.value,
        中断終了日時: resumeTime.value,
        中断理由区分: '作業再開',
        中断理由詳細: `再開理由: ${resumeReason} - ${resumeReasonDetail.value}`,
        中断時間: 0,
        影響度: '軽微',
        対応状況: '解決済み',
        記録者ID: 'current-user-id'
      });

      alert('作業を再開しました');

      // 工数入力画面に遷移
      window.showScreen("scr-1778907296658");

    } catch (error) {
      console.error('作業再開エラー:', error);
      alert('作業再開に失敗しました');
    }
  }

  // 初期データの読み込みと描画
  async function loadData() {
    try {
      const workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      const interruptRecords = await window.aivicApi.list(2) || tables[2]?.records || [];
      renderSuspendedWorks(workRecords, interruptRecords);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderSuspendedWorks(tables[1]?.records || [], tables[2]?.records || []);
    }
  }

  // イベントリスナーの設定

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    history.back();
  });

  // 再開ボタンクリック（行レベル）
  container.addEventListener('click', async (e) => {
    const resumeBtn = e.target.closest('.resume-work-btn');
    if (resumeBtn) {
      const workId = resumeBtn.dataset.workId;
      const interruptId = resumeBtn.dataset.interruptId;

      // 作業記録と中断記録を取得
      const workRecords = await window.aivicApi.list(1) || [];
      const interruptRecords = await window.aivicApi.list(2) || [];

      selectedWorkRecord = workRecords.find(w => w.作業記録ID === workId);
      selectedInterruptRecord = interruptRecords.find(i => i.中断記録ID === interruptId);

      if (selectedWorkRecord) {
        showSelectedWorkInfo(selectedWorkRecord, selectedInterruptRecord);
      }
    }
  });

  // 再開理由選択の変更
  resumeReasonSelect.addEventListener('change', (e) => {
    if (e.target.value && e.target.value !== 'その他') {
      resumeReasonDetail.value = e.target.value;
      updateCharCount();
    }
  });

  // 文字数カウント
  resumeReasonDetail.addEventListener('input', updateCharCount);

  // キャンセルボタン
  container.querySelector('#btn-cancel-resume').addEventListener('click', () => {
    resumeForm.classList.add('hidden');
    selectedWorkRecord = null;
    selectedInterruptRecord = null;
    resumeReasonDetail.value = '';
    resumeReasonSelect.value = '';
    updateCharCount();
  });

  // 作業再開ボタン
  container.querySelector('#btn-resume-work').addEventListener('click', () => {
    if (validateForm()) {
      confirmDialog.classList.remove('hidden');
    }
  });

  // 確認ダイアログ - OK
  container.querySelector('#btn-dialog-ok').addEventListener('click', () => {
    confirmDialog.classList.add('hidden');
    resumeWork();
  });

  // 確認ダイアログ - キャンセル
  container.querySelector('#btn-dialog-cancel').addEventListener('click', () => {
    confirmDialog.classList.add('hidden');
  });

  // ダイアログ背景クリックで閉じる
  confirmDialog.addEventListener('click', (e) => {
    if (e.target === confirmDialog) {
      confirmDialog.classList.add('hidden');
    }
  });

  // 初期化
  setCurrentTime();
  updateCharCount();
  loadData();
}

function(container, apiUrl, tables) {
  // エラー情報の管理
  let errorState = {
    title: 'システムエラーが発生しました',
    message: '作業記録の保存中にエラーが発生しました。ネットワーク接続を確認してください。',
    code: 'E001-NETWORK_ERROR',
    timestamp: new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }),
    solution: '1. ネットワーク接続を確認してください\n2. しばらく時間をおいて再試行してください\n3. 問題が解決しない場合は管理者にお問い合わせください',
    details: 'TypeError: Failed to fetch\n  at saveWorkRecord (work-record.js:45)\n  at HTMLButtonElement.<anonymous> (work-record.js:12)',
    previousScreen: 'scr-1778907133295', // 工数記録画面
    retryAction: null,
    isDetailsVisible: false,
    isNetworkError: true
  };

  // URLパラメータからエラー情報を取得
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      errorState = { ...errorState, ...errorData };
    } catch (e) {
      console.warn('エラーパラメータの解析に失敗:', e);
    }
  }

  // エラー情報を画面に反映
  function updateErrorDisplay() {
    container.querySelector('#error-title').textContent = errorState.title;
    container.querySelector('#error-message').textContent = errorState.message;
    container.querySelector('#error-code').textContent = errorState.code;
    container.querySelector('#error-timestamp').textContent = errorState.timestamp;
    container.querySelector('#error-solution').innerHTML = errorState.solution.replace(/\n/g, '<br>');
    container.querySelector('#error-stack').innerHTML = errorState.details.replace(/\n/g, '<br>').replace(/ /g, '&nbsp;');

    // 長いメッセージの制限（500文字以下）
    const messageEl = container.querySelector('#error-message');
    if (errorState.message.length > 500) {
      messageEl.textContent = errorState.message.substring(0, 497) + '...';
    }
  }

  updateErrorDisplay();

  // 再試行ボタン
  let isRetrying = false;
  container.querySelector('#btn-retry').addEventListener('click', async () => {
    if (isRetrying) return;

    isRetrying = true;
    const retryBtn = container.querySelector('#btn-retry');
    const originalText = retryBtn.textContent;
    retryBtn.textContent = '再試行中...';
    retryBtn.disabled = true;

    try {
      // ネットワークエラーの場合の再試行シミュレーション
      if (errorState.isNetworkError) {
        // 実際のネットワーク状態をチェック
        if (!navigator.onLine) {
          throw new Error('ネットワーク接続がありません');
        }

        // 簡単な接続テスト
        const response = await fetch(apiUrl + '/api/health', { 
          method: 'GET',
          timeout: 5000 
        }).catch(() => {
          throw new Error('サーバーに接続できません');
        });

        if (!response.ok) {
          throw new Error('サーバーエラーが発生しています');
        }
      }

      // 再試行成功 - 元の画面に戻る
      if (errorState.previousScreen) {
        window.showScreen(errorState.previousScreen);
      } else {
        window.showScreen('scr-1778907133295'); // デフォルトで工数記録画面
      }
    } catch (error) {
      // 再試行失敗
      errorState.message = `再試行に失敗しました。${error.message}`;
      errorState.timestamp = new Date().toLocaleString('ja-JP', {
        year: 'numeric',
        month: '2-digit', 
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit'
      });
      updateErrorDisplay();
    } finally {
      isRetrying = false;
      retryBtn.textContent = originalText;
      retryBtn.disabled = false;
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    if (errorState.previousScreen) {
      window.showScreen(errorState.previousScreen);
    } else {
      window.showScreen('scr-1778907133295'); // デフォルトで工数記録画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面をホームとする
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact-admin').addEventListener('click', async () => {
    try {
      // 管理者連絡機能の利用可能性をチェック
      const response = await fetch(apiUrl + '/api/contact/admin', {
        method: 'HEAD'
      }).catch(() => {
        throw new Error('連絡機能が利用できません');
      });

      if (!response.ok) {
        throw new Error('連絡機能が利用できません');
      }

      // 緊急報告画面に遷移
      window.showScreen('scr-1778907330826');
    } catch (error) {
      // 管理者連絡機能エラーを表示
      const contactError = container.querySelector('#contact-error');
      contactError.classList.remove('hidden');

      setTimeout(() => {
        contactError.classList.add('hidden');
      }, 10000); // 10秒後に自動で非表示
    }
  });

  // エラー詳細表示切り替えボタン
  container.querySelector('#btn-toggle-details').addEventListener('click', () => {
    const detailsEl = container.querySelector('#error-details');
    const toggleBtn = container.querySelector('#btn-toggle-details');

    errorState.isDetailsVisible = !errorState.isDetailsVisible;

    if (errorState.isDetailsVisible) {
      detailsEl.classList.remove('hidden');
      toggleBtn.textContent = 'エラー詳細を非表示';
    } else {
      detailsEl.classList.add('hidden');
      toggleBtn.textContent = 'エラー詳細を表示';
    }
  });

  // セッション切れの検出
  const checkSession = async () => {
    try {
      const response = await fetch(apiUrl + '/api/auth/check', {
        method: 'GET',
        credentials: 'include'
      });

      if (response.status === 401) {
        // セッション切れの場合
        errorState.title = 'セッションが切れました';
        errorState.message = 'ログインセッションの有効期限が切れています。再度ログインしてください。';
        errorState.code = 'E401-SESSION_EXPIRED';
        errorState.solution = '1. ログイン画面に移動してください\n2. 認証情報を入力し直してください';
        updateErrorDisplay();

        // ログイン画面へのボタンを追加
        const homeBtn = container.querySelector('#btn-home');
        homeBtn.textContent = 'ログイン画面へ';
        homeBtn.onclick = () => {
          window.location.href = './login.html';
        };
      }
    } catch (error) {
      // ネットワークエラーの場合は何もしない
    }
  };

  // 初期化時にセッションチェック
  checkSession();

  // ネットワーク状態の監視
  window.addEventListener('online', () => {
    if (errorState.isNetworkError) {
      errorState.message = 'ネットワーク接続が復旧しました。再試行してください。';
      updateErrorDisplay();
    }
  });

  window.addEventListener('offline', () => {
    errorState.title = 'ネットワークエラー';
    errorState.message = 'インターネット接続が切断されています。接続を確認してください。';
    errorState.code = 'E000-OFFLINE';
    errorState.isNetworkError = true;
    updateErrorDisplay();
  });
}

function(container, apiUrl, tables) {
  let currentEditId = null;
  let isValidating = false;
  let allValidationResults = [];

  // 重要度レベルのバッジ色
  function getSeverityBadge(severity) {
    const colors = {
      '高': '#ff4757',
      '中': '#ffa502', 
      '低': '#2ed573'
    };
    const color = colors[severity] || '#6c757d';
    return `<span style="background: ${color}; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${severity}</span>`;
  }

  // 確認状況のバッジ色
  function getStatusBadge(status) {
    const colors = {
      '未確認': '#ff4757',
      '確認済み': '#ffa502',
      '対応済み': '#2ed573'
    };
    const color = colors[status] || '#6c757d';
    return `<span style="background: ${color}; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">${status}</span>`;
  }

  // 検証結果テーブル再描画
  function renderValidationResults(results) {
    const tbody = container.querySelector('#validation-tbody');
    const noResults = container.querySelector('#no-results');

    if (!results || results.length === 0) {
      tbody.innerHTML = '';
      noResults.classList.remove('hidden');
      return;
    }

    noResults.classList.add('hidden');
    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id}" style="border-bottom: 1px solid rgba(255,255,255,0.05);">
        <td style="padding: 6px 10px; font-size: 13px;">
          <input type="checkbox" class="row-checkbox" data-id="${r.id}" style="accent-color: var(--primary);">
        </td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${new Date(r.検出日時 || r.作成日時).toLocaleString()}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.ユーザー名 || 'N/A'}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.異常値種別 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.検出項目 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${r.検出値 || ''}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${getSeverityBadge(r.重要度 || '低')}</td>
        <td style="padding: 6px 10px; font-size: 13px;">${getStatusBadge(r.確認状況 || '未確認')}</td>
        <td style="padding: 6px 10px; font-size: 13px;">
          <button class="action-btn secondary edit-btn" data-id="${r.id}" style="margin-right: 4px;">修正</button>
        </td>
      </tr>
    `).join('');
  }

  // 初期データ表示
  async function loadValidationResults() {
    try {
      const results = await window.aivicApi.list(4); // 異常値検出ログテーブル
      allValidationResults = results || [];
      renderValidationResults(allValidationResults);
    } catch (error) {
      console.error('検証結果の読み込みに失敗しました:', error);
      allValidationResults = tables[4]?.records || [];
      renderValidationResults(allValidationResults);
    }
  }

  // 検証実行
  async function executeValidation() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;

    if (!startDate || !endDate) {
      alert('検証対象期間を選択してください');
      return;
    }

    if (isValidating) {
      alert('検証処理が実行中です。しばらくお待ちください。');
      return;
    }

    isValidating = true;
    const progressArea = container.querySelector('#progress-area');
    const progressBar = container.querySelector('#progress-bar');
    const progressText = container.querySelector('#progress-text');
    const validateBtn = container.querySelector('#btn-validate');

    progressArea.classList.remove('hidden');
    validateBtn.disabled = true;
    validateBtn.style.opacity = '0.6';

    // 進捗バーアニメーション
    let progress = 0;
    const progressInterval = setInterval(() => {
      progress += Math.random() * 15;
      if (progress > 90) progress = 90;
      progressBar.style.width = progress + '%';
      progressText.textContent = Math.round(progress) + '%';
    }, 200);

    try {
      // 作業記録データを取得して検証
      const workRecords = await window.aivicApi.list(1);
      const filteredRecords = workRecords.filter(record => {
        const workDate = new Date(record.作業日);
        return workDate >= new Date(startDate) && workDate <= new Date(endDate);
      });

      // 異常値検出ロジック
      const anomalies = [];
      filteredRecords.forEach(record => {
        // 長時間作業チェック
        if (record.作業時間 && record.作業時間 > 720) { // 12時間以上
          anomalies.push({
            id: 'anom_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
            検出対象テーブル: '作業記録',
            検出対象レコードID: record.id,
            ユーザーID: record.作業員ID,
            ユーザー名: record.作業員名 || 'N/A',
            異常値種別: '時間異常',
            検出項目: '作業時間',
            検出値: record.作業時間 + '分',
            閾値: '720分',
            重要度: '高',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: new Date().toISOString(),
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          });
        }

        // 必須項目チェック
        if (!record.作業内容 || record.作業内容.trim() === '') {
          anomalies.push({
            id: 'anom_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
            検出対象テーブル: '作業記録',
            検出対象レコードID: record.id,
            ユーザーID: record.作業員ID,
            ユーザー名: record.作業員名 || 'N/A',
            異常値種別: '必須項目',
            検出項目: '作業内容',
            検出値: '空白',
            閾値: '必須',
            重要度: '中',
            確認状況: '未確認',
            通知送信フラグ: false,
            検出日時: new Date().toISOString(),
            作成日時: new Date().toISOString(),
            更新日時: new Date().toISOString()
          });
        }
      });

      // 進捗完了
      clearInterval(progressInterval);
      progressBar.style.width = '100%';
      progressText.textContent = '100%';

      // 異常値をデータベースに保存
      for (const anomaly of anomalies) {
        await window.aivicApi.save(4, anomaly);
      }

      setTimeout(() => {
        progressArea.classList.add('hidden');
        validateBtn.disabled = false;
        validateBtn.style.opacity = '1';
        isValidating = false;

        // 完了通知表示
        const notification = container.querySelector('#notification-area');
        notification.textContent = `データ検証が完了しました。${anomalies.length}件の異常値が検出されました。`;
        notification.classList.remove('hidden');
        setTimeout(() => notification.classList.add('hidden'), 5000);

        // 結果を再読み込み
        loadValidationResults();
      }, 500);

    } catch (error) {
      clearInterval(progressInterval);
      progressArea.classList.add('hidden');
      validateBtn.disabled = false;
      validateBtn.style.opacity = '1';
      isValidating = false;
      alert('検証処理中にエラーが発生しました: ' + error.message);
    }
  }

  // エラー種別フィルター
  function applyErrorFilter() {
    const filterValue = container.querySelector('#error-filter').value;
    let filteredResults = allValidationResults;

    if (filterValue) {
      filteredResults = allValidationResults.filter(r => r.異常値種別 === filterValue);
    }

    renderValidationResults(filteredResults);
  }

  // 一括承認
  async function bulkApprove() {
    const checkboxes = container.querySelectorAll('.row-checkbox:checked');

    if (checkboxes.length === 0) {
      alert('承認する項目を選択してください');
      return;
    }

    if (!confirm(`${checkboxes.length}件のデータを承認しますか？`)) {
      return;
    }

    try {
      for (const checkbox of checkboxes) {
        const id = checkbox.dataset.id;
        await window.aivicApi.update(4, id, {
          確認状況: '対応済み',
          確認者ID: 'current_user_id',
          確認日時: new Date().toISOString(),
          対応メモ: '一括承認により対応済み',
          更新日時: new Date().toISOString()
        });
      }

      alert('一括承認が完了しました');
      loadValidationResults();
    } catch (error) {
      alert('一括承認中にエラーが発生しました: ' + error.message);
    }
  }

  // ログ出力
  async function exportLog() {
    if (allValidationResults.length === 0) {
      alert('検証結果がありません');
      return;
    }

    try {
      const csvHeader = '検出日時,作業員,エラー種別,検出項目,検出値,重要度,確認状況,対応メモ\n';
      const csvData = allValidationResults.map(r => [
        new Date(r.検出日時 || r.作成日時).toLocaleString(),
        r.ユーザー名 || 'N/A',
        r.異常値種別 || '',
        r.検出項目 || '',
        r.検出値 || '',
        r.重要度 || '',
        r.確認状況 || '',
        (r.対応メモ || '').replace(/"/g, '""')
      ].map(field => `"${field}"`).join(',')).join('\n');

      const csv = '\uFEFF' + csvHeader + csvData;
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `validation_log_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (error) {
      alert('ログ出力中にエラーが発生しました: ' + error.message);
    }
  }

  // 再検証
  async function revalidate() {
    if (!confirm('再検証を実行しますか？')) {
      return;
    }

    executeValidation();
  }

  // 修正モーダル表示
  function showEditModal(id) {
    const record = allValidationResults.find(r => r.id === id);
    if (!record) return;

    currentEditId = id;
    const modal = container.querySelector('#edit-modal');

    // 関連する作業記録を取得して初期値設定（簡略化）
    container.querySelector('#edit-start-time').value = '';
    container.querySelector('#edit-end-time').value = '';
    container.querySelector('#edit-content').value = '';
    container.querySelector('#edit-memo').value = record.対応メモ || '';

    modal.classList.remove('hidden');
  }

  // 修正保存
  async function saveEdit() {
    if (!currentEditId) return;

    const startTime = container.querySelector('#edit-start-time').value;
    const endTime = container.querySelector('#edit-end-time').value;
    const content = container.querySelector('#edit-content').value;
    const memo = container.querySelector('#edit-memo').value;

    // 入力値検証
    if (content.length > 1000) {
      alert('作業内容は1000文字以内で入力してください');
      return;
    }

    if (startTime && endTime && new Date(startTime) >= new Date(endTime)) {
      alert('終了時刻は開始時刻より後の時刻を入力してください');
      return;
    }

    try {
      // 異常値検出ログを更新
      await window.aivicApi.update(4, currentEditId, {
        確認状況: '対応済み',
        確認者ID: 'current_user_id',
        確認日時: new Date().toISOString(),
        対応メモ: memo,
        更新日時: new Date().toISOString()
      });

      container.querySelector('#edit-modal').classList.add('hidden');
      currentEditId = null;
      loadValidationResults();
      alert('修正が完了しました');
    } catch (error) {
      alert('修正保存中にエラーが発生しました: ' + error.message);
    }
  }

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', (e) => {
    const checkboxes = container.querySelectorAll('.row-checkbox');
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // イベントリスナー登録
  container.querySelector('#btn-validate').addEventListener('click', executeValidation);
  container.querySelector('#error-filter').addEventListener('change', applyErrorFilter);
  container.querySelector('#btn-bulk-approve').addEventListener('click', bulkApprove);
  container.querySelector('#btn-export-log').addEventListener('click', exportLog);
  container.querySelector('#btn-revalidate').addEventListener('click', revalidate);
  container.querySelector('#btn-cancel-edit').addEventListener('click', () => {
    container.querySelector('#edit-modal').classList.add('hidden');
    currentEditId = null;
  });
  container.querySelector('#btn-save-edit').addEventListener('click', saveEdit);

  // 行レベル操作のイベントデリゲーション
  container.addEventListener('click', (e) => {
    const editBtn = e.target.closest('.edit-btn');
    if (editBtn) {
      showEditModal(editBtn.dataset.id);
    }
  });

  // 初期データ読み込み
  loadValidationResults();
}

function(container, apiUrl, tables) {
  let interruptions = [];
  let currentUser = null;

  // 現在のユーザー情報を取得（仮想的に最初のユーザーを使用）
  if (tables[0] && tables[0].records && tables[0].records.length > 0) {
    currentUser = tables[0].records[0];
    container.querySelector('#worker-name').value = currentUser.氏名 || '';
  }

  // 作業項目マスタを読み込み
  async function loadWorkItems() {
    try {
      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      const select = container.querySelector('#work-item');
      select.innerHTML = '<option value="">選択してください</option>';

      if (workItems) {
        workItems
          .filter(item => item.有効フラグ)
          .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
          .forEach(item => {
            const option = document.createElement('option');
            option.value = item.作業項目ID;
            option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
            select.appendChild(option);
          });
      }
    } catch (error) {
      console.error('作業項目の読み込みに失敗しました:', error);
    }
  }

  // 実働時間を計算
  function calculateWorkTime() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#actual-work-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    // 24時間をまたぐ場合
    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const actualMinutes = diffMinutes - breakTime;

    if (actualMinutes < 0) {
      container.querySelector('#actual-work-time').value = '';
      return;
    }

    const hours = Math.floor(actualMinutes / 60);
    const minutes = actualMinutes % 60;
    container.querySelector('#actual-work-time').value = `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // 中断記録を表示
  function renderInterruptions() {
    const tbody = container.querySelector('#interruption-tbody');
    tbody.innerHTML = interruptions.map((int, index) => {
      const duration = int.終了時刻 ? calculateInterruptionDuration(int.開始時刻, int.終了時刻) : '進行中';
      return `
        <tr>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.08);">${int.理由}</td>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.08);">${int.開始時刻}</td>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.08);">${int.終了時刻 || '-'}</td>
          <td style="padding: 6px 10px; color: var(--text); border-bottom: 1px solid rgba(255,255,255,0.08);">${duration}</td>
          <td style="padding: 6px 10px; text-align: center; border-bottom: 1px solid rgba(255,255,255,0.08);">
            <button class="delete-interruption" data-index="${index}" 
                    style="background: transparent; color: #ff6666; border: 1px solid #ff6666; padding: 2px 8px; border-radius: 4px; font-size: 11px; cursor: pointer;">
              削除
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 中断時間を計算
  function calculateInterruptionDuration(startTime, endTime) {
    if (!startTime || !endTime) return '';

    const start = new Date(`2000-01-01 ${startTime}`);
    let end = new Date(`2000-01-01 ${endTime}`);

    if (end < start) {
      end.setDate(end.getDate() + 1);
    }

    const diffMs = end - start;
    const diffMinutes = Math.floor(diffMs / (1000 * 60));
    const hours = Math.floor(diffMinutes / 60);
    const minutes = diffMinutes % 60;

    return `${hours}時間${minutes.toString().padStart(2, '0')}分`;
  }

  // エラーメッセージを表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const workDate = container.querySelector('#work-date').value;
    const workItem = container.querySelector('#work-item').value;
    const workLocation = container.querySelector('#work-location').value;
    const startTime = container.querySelector('#start-time').value;
    const workDetails = container.querySelector('#work-details').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = parseInt(container.querySelector('#break-time').value) || 0;

    // 必須項目チェック
    if (!workDate || !workItem || !workLocation || !startTime || !workDetails) {
      showError('必須項目が入力されていません。');
      return false;
    }

    // 未来日付チェック
    const today = new Date();
    const selectedDate = new Date(workDate);
    if (selectedDate > today) {
      showError('未来の日付は選択できません。');
      return false;
    }

    // 時刻フォーマットチェック
    const timeRegex = /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/;
    if (!timeRegex.test(startTime)) {
      showError('開始時刻の形式が正しくありません。');
      return false;
    }

    if (endTime && !timeRegex.test(endTime)) {
      showError('終了時刻の形式が正しくありません。');
      return false;
    }

    // 開始時刻と終了時刻の関係チェック
    if (endTime) {
      if (startTime === endTime) {
        showError('開始時刻と終了時刻が同じです。');
        return false;
      }

      const start = new Date(`2000-01-01 ${startTime}`);
      let end = new Date(`2000-01-01 ${endTime}`);

      if (end < start) {
        end.setDate(end.getDate() + 1);
      }

      const diffMs = end - start;
      const diffMinutes = Math.floor(diffMs / (1000 * 60));

      if (breakTime > diffMinutes) {
        showError('休憩時間が実働時間を超過しています。');
        return false;
      }
    }

    // 文字数チェック
    if (workDetails.length > 1000) {
      showError('作業内容詳細は1000文字以内で入力してください。');
      return false;
    }

    return true;
  }

  // 初期化
  loadWorkItems();

  // 今日の日付をデフォルトに設定
  const today = new Date();
  container.querySelector('#work-date').value = today.toISOString().split('T')[0];

  // イベントリスナー
  container.querySelector('#start-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#end-time').addEventListener('change', calculateWorkTime);
  container.querySelector('#break-time').addEventListener('input', calculateWorkTime);

  // 文字数カウント
  container.querySelector('#work-details').addEventListener('input', function() {
    const count = this.value.length;
    container.querySelector('#char-count').textContent = count;
    if (count > 1000) {
      this.style.borderColor = '#cc0000';
    } else {
      this.style.borderColor = 'rgba(255,255,255,0.18)';
    }
  });

  // 進捗状況変更時の中断セクション表示/非表示
  container.querySelector('#progress-status').addEventListener('change', function() {
    const interruptionSection = container.querySelector('#interruption-section');
    if (this.value === '中断') {
      interruptionSection.style.display = 'block';
    } else {
      interruptionSection.style.display = 'none';
    }
  });

  // 中断記録追加
  container.querySelector('#add-interruption').addEventListener('click', function() {
    const reason = container.querySelector('#interruption-reason').value;
    const startTime = container.querySelector('#interruption-start').value;
    const endTime = container.querySelector('#interruption-end').value;

    if (!reason || !startTime) {
      showError('中断理由と開始時刻は必須です。');
      return;
    }

    const interruption = {
      理由: reason,
      開始時刻: startTime,
      終了時刻: endTime
    };

    interruptions.push(interruption);
    renderInterruptions();

    // フォームクリア
    container.querySelector('#interruption-start').value = '';
    container.querySelector('#interruption-end').value = '';
  });

  // 中断記録削除
  container.addEventListener('click', function(e) {
    if (e.target.classList.contains('delete-interruption')) {
      const index = parseInt(e.target.dataset.index);
      interruptions.splice(index, 1);
      renderInterruptions();
    }
  });

  // 作業中断ボタン
  container.querySelector('#btn-interrupt').addEventListener('click', function() {
    window.showScreen("scr-1778907238439");
  });

  // 登録ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) return;

    const workData = {
      作業員ID: currentUser?.ユーザーID || '',
      作業日: new Date(container.querySelector('#work-date').value).toISOString(),
      作業開始時刻: new Date(`${container.querySelector('#work-date').value} ${container.querySelector('#start-time').value}`).toISOString(),
      作業終了時刻: container.querySelector('#end-time').value ? 
        new Date(`${container.querySelector('#work-date').value} ${container.querySelector('#end-time').value}`).toISOString() : null,
      プロジェクト名: container.querySelector('#work-item option:checked').textContent.split(' - ')[1] || '',
      作業場所: container.querySelector('#work-location').value,
      作業種別: container.querySelector('#work-item option:checked').textContent.split(' - ')[0] || '',
      作業内容: container.querySelector('#work-details').value,
      進捗状況: container.querySelector('#progress-status').value,
      備考: container.querySelector('#remarks').value,
      承認状態: '未承認',
      作成者ID: currentUser?.ユーザーID || ''
    };

    try {
      const saved = await window.aivicApi.save(1, workData); // 作業記録テーブル

      if (saved) {
        // 中断記録も保存
        for (const interruption of interruptions) {
          const interruptionData = {
            作業記録ID: saved.作業記録ID,
            中断開始日時: new Date(`${container.querySelector('#work-date').value} ${interruption.開始時刻}`).toISOString(),
            中断終了日時: interruption.終了時刻? 
              new Date(`${container.querySelector('#work-date').value} ${interruption.終了時刻}`).toISOString() : null,
            中断理由区分: interruption.理由,
            対応状況: '未対応',
            記録者ID: currentUser?.ユーザーID || ''
          };

          await window.aivicApi.save(2, interruptionData); // 中断記録テーブル
        }

        alert('工数記録を登録しました。');

        // フォームリセット
        container.querySelector('#work-entry-form').reset();
        container.querySelector('#work-date').value = today.toISOString().split('T')[0];
        container.querySelector('#worker-name').value = currentUser?.氏名 || '';
        container.querySelector('#actual-work-time').value = '';
        container.querySelector('#char-count').textContent = '0';
        interruptions = [];
        renderInterruptions();
        container.querySelector('#interruption-section').style.display = 'none';
      }
    } catch (error) {
      showError('工数記録の登録に失敗しました。');
    }
  });

  // 作業終了ボタン
  container.querySelector('#btn-complete').addEventListener('click', function() {
    window.showScreen("scr-1778907199709");
  });
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let breakRecords = [];
  let workItems = [];
  let selectedRecord = null;

  // 初期データ読み込み
  async function loadData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      breakRecords = await window.aivicApi.list(2) || tables[2]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      populateRecordSelect();
      populateWorkItems();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // 修正対象記録のプルダウンを設定
  function populateRecordSelect() {
    const select = container.querySelector('#target-record');
    select.innerHTML = '<option value="">記録を選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.作業記録ID || record.id;
      const date = record.作業日 ? new Date(record.作業日).toLocaleDateString() : '';
      const project = record.プロジェクト名 || '';
      const workType = record.作業種別 || '';
      option.textContent = `${date} - ${project} - ${workType}`;
      select.appendChild(option);
    });
  }

  // 作業項目のプルダウンを設定
  function populateWorkItems() {
    const select = container.querySelector('#work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems.filter(item => item.有効フラグ).forEach(item => {
      const option = document.createElement('option');
      option.value = item.作業項目ID || item.id;
      option.textContent = `${item.作業項目コード || ''} - ${item.作業項目名 || ''}`;
      select.appendChild(option);
    });
  }

  // 修正前データを表示
  function showOriginalData(record) {
    const originalDataDiv = container.querySelector('#original-data');
    const contentDiv = container.querySelector('#original-data-content');

    const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
    const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'}) : '';
    const workDate = record.作業日 ? new Date(record.作業日).toLocaleDateString() : '';

    contentDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
        <div>作業日: ${workDate}</div>
        <div>プロジェクト: ${record.プロジェクト名 || ''}</div>
        <div>開始時刻: ${startTime}</div>
        <div>終了時刻: ${endTime}</div>
        <div>作業種別: ${record.作業種別 || ''}</div>
        <div>進捗状況: ${record.進捗状況 || ''}</div>
      </div>
    `;

    originalDataDiv.style.display = 'block';
  }

  // フォームに値を設定
  function populateForm(record) {
    if (record.作業日) {
      container.querySelector('#work-date').value = new Date(record.作業日).toISOString().split('T')[0];
    }

    if (record.作業開始時刻) {
      container.querySelector('#start-time').value = new Date(record.作業開始時刻).toTimeString().slice(0, 5);
    }

    if (record.作業終了時刻) {
      container.querySelector('#end-time').value = new Date(record.作業終了時刻).toTimeString().slice(0, 5);
    }

    // 中断記録があれば設定
    const breakRecord = breakRecords.find(br => br.作業記録ID === record.作業記録ID);
    if (breakRecord) {
      if (breakRecord.中断開始日時) {
        container.querySelector('#break-time').value = new Date(breakRecord.中断開始日時).toTimeString().slice(0, 5);
      }
      container.querySelector('#break-reason').value = breakRecord.中断理由区分 || '';
    }

    calculateTimes();
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = container.querySelector('#break-time').value;

    let actualWorkMinutes = 0;
    let breakDuration = 0;

    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (end > start) {
        const totalMinutes = (end - start) / (1000 * 60);

        if (breakTime) {
          const breakStart = new Date(`2000-01-01T${breakTime}:00`);
          if (breakStart >= start && breakStart <= end) {
            // 簡易計算: 中断時間を30分と仮定
            breakDuration = 30;
          }
        }

        actualWorkMinutes = totalMinutes - breakDuration;
      }
    }

    container.querySelector('#break-duration').textContent = `${breakDuration}分`;

    const hours = Math.floor(actualWorkMinutes / 60);
    const minutes = actualWorkMinutes % 60;
    container.querySelector('#actual-work-time').textContent = `${hours}時間${minutes}分`;
  }

  // バリデーション
  function validateForm() {
    const warnings = [];
    const errors = [];

    const workDate = container.querySelector('#work-date').value;
    const startTime = container.querySelector('#start-time').value;
    const endTime = container.querySelector('#end-time').value;
    const breakTime = container.querySelector('#break-time').value;
    const correctionReason = container.querySelector('#correction-reason').value.trim();

    // 必須チェック
    if (!workDate) errors.push('作業日付を入力してください');
    if (!startTime) errors.push('作業開始時刻を入力してください');
    if (!endTime) errors.push('作業終了時刻を入力してください');
    if (!correctionReason) errors.push('修正理由を入力してください');

    // 日付チェック
    if (workDate) {
      const date = new Date(workDate);
      const today = new Date();
      const minDate = new Date('1900-01-01');
      const maxDate = new Date('2099-12-31');

      if (date > today) {
        errors.push('作業日付に未来の日付は入力できません');
      }
      if (date < minDate || date > maxDate) {
        errors.push('作業日付は1900年1月1日から2099年12月31日の間で入力してください');
      }
    }

    // 時刻チェック
    if (startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);

      if (start >= end) {
        errors.push('開始時刻は終了時刻より前の時刻を入力してください');
      }

      const totalHours = (end - start) / (1000 * 60 * 60);
      if (totalHours > 20) {
        warnings.push('作業時間が20時間を超えています。異常な長時間作業の可能性があります。');
      }
    }

    // 中断時刻チェック
    if (breakTime && startTime && endTime) {
      const start = new Date(`2000-01-01T${startTime}:00`);
      const end = new Date(`2000-01-01T${endTime}:00`);
      const breakStart = new Date(`2000-01-01T${breakTime}:00`);

      if (breakStart < start || breakStart > end) {
        errors.push('中断時刻が作業時間外です');
      }
    }

    return { warnings, errors };
  }

  // 警告・エラー表示
  function showValidationResults(warnings, errors) {
    const warningArea = container.querySelector('#warning-area');
    const errorArea = container.querySelector('#error-area');

    if (warnings.length > 0) {
      const warningList = container.querySelector('#warning-list');
      warningList.innerHTML = warnings.map(w => `<li>${w}</li>`).join('');
      warningArea.style.display = 'block';
    } else {
      warningArea.style.display = 'none';
    }

    if (errors.length > 0) {
      container.querySelector('#error-message').textContent = errors[0];
      errorArea.style.display = 'block';
      return false;
    } else {
      errorArea.style.display = 'none';
      return true;
    }
  }

  // 文字数カウント
  container.querySelector('#correction-reason').addEventListener('input', function() {
    const count = this.value.length;
    container.querySelector('#char-count').textContent = count;
  });

  // 修正対象記録選択
  container.querySelector('#target-record').addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      container.querySelector('#edit-form').style.display = 'none';
      container.querySelector('#original-data').style.display = 'none';
      return;
    }

    selectedRecord = workRecords.find(r => (r.作業記録ID || r.id) === recordId);
    if (selectedRecord) {
      showOriginalData(selectedRecord);
      populateForm(selectedRecord);
      container.querySelector('#edit-form').style.display = 'block';
    }
  });

  // 時刻変更時の計算
  ['#start-time', '#end-time', '#break-time'].forEach(selector => {
    container.querySelector(selector).addEventListener('change', calculateTimes);
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    window.showScreen('scr-1778907145716'); // 作業履歴一覧画面
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!selectedRecord) {
      showValidationResults([], ['修正対象の記録が選択されていません']);
      return;
    }

    const { warnings, errors } = validateForm();
    if (!showValidationResults(warnings, errors)) {
      return;
    }

    try {
      const workDate = container.querySelector('#work-date').value;
      const startTime = container.querySelector('#start-time').value;
      const endTime = container.querySelector('#end-time').value;
      const workItem = container.querySelector('#work-item').value;
      const breakTime = container.querySelector('#break-time').value;
      const breakReason = container.querySelector('#break-reason').value;
      const correctionReason = container.querySelector('#correction-reason').value.trim();

      // 作業記録更新
      const updateData = {
        作業日: new Date(workDate).toISOString(),
        作業開始時刻: new Date(`${workDate}T${startTime}:00`).toISOString(),
        作業終了時刻: new Date(`${workDate}T${endTime}:00`).toISOString(),
        更新日時: new Date().toISOString()
      };

      if (workItem) {
        const selectedWorkItem = workItems.find(wi => (wi.作業項目ID || wi.id) === workItem);
        if (selectedWorkItem) {
          updateData.作業種別 = selectedWorkItem.作業項目名;
        }
      }

      await window.aivicApi.update(1, selectedRecord.作業記録ID || selectedRecord.id, updateData);

      // 中断記録の更新/作成
      if (breakTime && breakReason) {
        const existingBreak = breakRecords.find(br => br.作業記録ID === (selectedRecord.作業記録ID || selectedRecord.id));
        const breakData = {
          作業記録ID: selectedRecord.作業記録ID || selectedRecord.id,
          中断開始日時: new Date(`${workDate}T${breakTime}:00`).toISOString(),
          中断理由区分: breakReason,
          対応状況: '記録済み',
          記録者ID: selectedRecord.作業員ID,
          更新日時: new Date().toISOString()
        };

        if (existingBreak) {
          await window.aivicApi.update(2, existingBreak.中断記録ID || existingBreak.id, breakData);
        } else {
          breakData.中断記録ID = crypto.randomUUID();
          breakData.作成日時 = new Date().toISOString();
          await window.aivicApi.save(2, breakData);
        }
      }

      // 異常値検出ログ作成（警告がある場合）
      if (warnings.length > 0) {
        const logData = {
          異常値検出ログID: crypto.randomUUID(),
          検出対象テーブル: '作業記録',
          検出対象レコードID: selectedRecord.作業記録ID || selectedRecord.id,
          ユーザーID: selectedRecord.作業員ID,
          異常値種別: '長時間作業',
          検出項目: '作業時間',
          検出値: container.querySelector('#actual-work-time').textContent,
          閾値: '20時間',
          重要度: '中',
          確認状況: '未確認',
          通知送信フラグ: false,
          検出日時: new Date().toISOString(),
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };

        await window.aivicApi.save(4, logData);
      }

      alert('修正が完了しました');
      window.showScreen('scr-1778907145716'); // 作業履歴一覧画面

    } catch (error) {
      console.error('保存エラー:', error);
      showValidationResults([], ['保存中にエラーが発生しました']);
    }
  });

  // 初期化
  loadData();
}

function(container, apiUrl, tables) {
  let selectedUrgency = '';
  let attachedFiles = [];
  let currentUser = null;

  // 現在のユーザー情報を取得
