      const workItems = await window.aivicApi.list(3); // 作業項目マスタ
      const select = container.querySelector('#work-item');
      if (workItems) {
        workItems.forEach(item => {
          if (item.有効フラグ) {
            const option = document.createElement('option');
            option.value = item.作業項目ID;
            option.textContent = item.作業項目名;
            select.appendChild(option);
          }
        });
      }
    } catch (error) {
      console.error('作業項目の取得に失敗:', error);
    }
  }

  // 緊急度ボタンの処理
  container.querySelectorAll('.urgency-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      container.querySelectorAll('.urgency-btn').forEach(b => {
        b.style.background = 'transparent';
        b.style.color = 'var(--text)';
      });
      btn.style.background = 'var(--primary)';
      btn.style.color = '#fff';
      selectedUrgency = btn.dataset.value;
      container.querySelector('#urgency-value').value = selectedUrgency;
    });
  });

  // 文字数カウンター
  const contentTextarea = container.querySelector('#emergency-content');
  const charCount = container.querySelector('#char-count');
  contentTextarea.addEventListener('input', () => {
    const count = contentTextarea.value.length;
    charCount.textContent = `(${count}/1000)`;
    if (count > 1000) {
      charCount.style.color = '#ef4444';
    } else {
      charCount.style.color = 'var(--text-muted)';
    }
  });

  // 写真添付処理
  const photoInput = container.querySelector('#photo-input');
  const photoBtn = container.querySelector('#photo-btn');
  const photoDropZone = container.querySelector('#photo-drop-zone');
  const photoPreview = container.querySelector('#photo-preview');

  photoBtn.addEventListener('click', () => {
    photoInput.click();
  });

  photoInput.addEventListener('change', handleFiles);

  // ドラッグ&ドロップ
  photoDropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    photoDropZone.style.borderColor = 'var(--primary)';
  });

  photoDropZone.addEventListener('dragleave', () => {
    photoDropZone.style.borderColor = 'rgba(255,255,255,0.18)';
  });

  photoDropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    photoDropZone.style.borderColor = 'rgba(255,255,255,0.18)';
    handleFiles({ target: { files: e.dataTransfer.files } });
  });

  function handleFiles(event) {
    const files = Array.from(event.target.files);

    for (const file of files) {
      // ファイル形式チェック
      if (!file.type.startsWith('image/')) {
        showError('サポートされていないファイル形式です。画像ファイルを選択してください。');
        continue;
      }

      // ファイルサイズチェック (10MB)
      if (file.size > 10 * 1024 * 1024) {
        showError('ファイルサイズが上限を超えています。10MB以下のファイルを選択してください。');
        continue;
      }

      // 枚数制限チェック
      if (attachedFiles.length >= 5) {
        showError('添付できる画像は最大5枚までです。');
        break;
      }

      attachedFiles.push(file);

      // プレビュー表示
      const reader = new FileReader();
      reader.onload = (e) => {
        const preview = document.createElement('div');
        preview.style.cssText = 'position: relative; display: inline-block;';
        preview.innerHTML = `
          <img src="${e.target.result}" style="width: 80px; height: 80px; object-fit: cover; border-radius: 4px; border: 1px solid rgba(255,255,255,0.18);" />
          <button type="button" class="remove-photo" data-index="${attachedFiles.length - 1}" style="position: absolute; top: -4px; right: -4px; width: 20px; height: 20px; border-radius: 50%; background: #ef4444; color: #fff; border: none; font-size: 12px; cursor: pointer;">×</button>
        `;
        photoPreview.appendChild(preview);
      };
      reader.readAsDataURL(file);
    }
  }

  // 写真削除
  photoPreview.addEventListener('click', (e) => {
    if (e.target.classList.contains('remove-photo')) {
      const index = parseInt(e.target.dataset.index);
      attachedFiles.splice(index, 1);
      e.target.closest('div').remove();

      // インデックスを再設定
      photoPreview.querySelectorAll('.remove-photo').forEach((btn, i) => {
        btn.dataset.index = i;
      });
    }
  });

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // バリデーション
  function validateForm() {
    const reportType = container.querySelector('#report-type').value;
    const occurrenceDateTime = container.querySelector('#occurrence-datetime').value;
    const occurrenceLocation = container.querySelector('#occurrence-location').value;
    const emergencyContent = container.querySelector('#emergency-content').value;
    const contactPhone = container.querySelector('#contact-phone').value;

    if (!selectedUrgency) {
      showError('緊急度を選択してください。');
      return false;
    }

    if (!reportType) {
      showError('報告種別を選択してください。');
      return false;
    }

    if (!occurrenceDateTime) {
      showError('発生日時を入力してください。');
      return false;
    }

    // 未来日付チェック
    const occurrenceDate = new Date(occurrenceDateTime);
    const now = new Date();
    if (occurrenceDate > now) {
      showError('発生日時に未来の日付は入力できません。');
      return false;
    }

    if (!occurrenceLocation.trim()) {
      showError('発生場所を入力してください。');
      return false;
    }

    if (!emergencyContent.trim()) {
      showError('緊急事態内容を入力してください。');
      return false;
    }

    if (emergencyContent.length > 1000) {
      showError('緊急事態内容は1000文字以内で入力してください。');
      return false;
    }

    if (!contactPhone.trim()) {
      showError('連絡先電話番号を入力してください。');
      return false;
    }

    // 電話番号形式チェック
    const phonePattern = /^(\d{2,4}-\d{2,4}-\d{4}|\d{10,11})$/;
    if (!phonePattern.test(contactPhone.replace(/[^\d-]/g, ''))) {
      showError('正しい電話番号の形式で入力してください。');
      return false;
    }

    return true;
  }

  // 下書き保存
  container.querySelector('#draft-save-btn').addEventListener('click', async () => {
    const formData = {
      緊急度: selectedUrgency,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#occurrence-location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#emergency-content').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      状態: '下書き',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    try {
      // 異常値検出ログテーブルに一時保存として記録
      await window.aivicApi.save(4, {
        検出対象テーブル: '緊急報告',
        検出対象レコードID: 'draft-' + Date.now(),
        ユーザーID: currentUser?.ユーザーID || 'unknown',
        異常値種別: '下書き保存',
        検出項目: '緊急報告内容',
        検出値: JSON.stringify(formData),
        閾値: '下書き',
        重要度: '低',
        確認状況: '未確認',
        通知送信フラグ: false,
        検出日時: new Date().toISOString(),
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      });

      alert('下書きが保存されました。');
    } catch (error) {
      showError('下書きの保存に失敗しました。');
    }
  });

  // 緊急報告送信
  container.querySelector('#submit-btn').addEventListener('click', async () => {
    if (!validateForm()) return;

    const formData = {
      緊急度: selectedUrgency,
      報告種別: container.querySelector('#report-type').value,
      発生日時: container.querySelector('#occurrence-datetime').value,
      発生場所: container.querySelector('#occurrence-location').value,
      作業項目ID: container.querySelector('#work-item').value,
      緊急事態内容: container.querySelector('#emergency-content').value,
      報告者名: container.querySelector('#reporter-name').value,
      連絡先電話番号: container.querySelector('#contact-phone').value,
      添付ファイル数: attachedFiles.length,
      状態: '送信済み',
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString()
    };

    try {
      // 異常値検出ログテーブルに緊急報告として記録
      const saved = await window.aivicApi.save(4, {
        検出対象テーブル: '緊急報告',
        検出対象レコードID: 'emergency-' + Date.now(),
        ユーザーID: currentUser?.ユーザーID || 'unknown',
        異常値種別: '緊急報告',
        検出項目: '緊急事態',
        検出値: formData.緊急事態内容,
        閾値: formData.緊急度,
        重要度: formData.緊急度,
        確認状況: '未確認',
        通知送信フラグ: true,
        検出日時: new Date().toISOString(),
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      });

      if (saved) {
        alert('緊急報告が送信されました。関係者に通知が送られます。');

        // 送信完了後の表示切り替え
        container.querySelector('#submit-btn').style.display = 'none';
        container.querySelector('#draft-save-btn').style.display = 'none';
        container.querySelector('#complete-btn').style.display = 'inline-block';

        // フォームを無効化
        const form = container.querySelector('#emergency-form');
        const inputs = form.querySelectorAll('input, select, textarea, button');
        inputs.forEach(input => input.disabled = true);
      } else {
        showError('緊急報告の送信に失敗しました。');
      }
    } catch (error) {
      showError('緊急報告の送信に失敗しました。');
    }
  });

  // 報告完了ボタン
  container.querySelector('#complete-btn').addEventListener('click', () => {
    window.showScreen("scr-1778907133295");
  });

  // 初期化
  loadCurrentUser();
  loadWorkItems();

  // 現在日時を設定
  const now = new Date();
  now.setMinutes(now.getMinutes() - now.getTimezoneOffset());
  container.querySelector('#occurrence-datetime').value = now.toISOString().slice(0, 16);
}

function(container, apiUrl, tables) {
  let workRecords = [];
  let workItems = [];
  let selectedRecord = null;
  let originalData = null;

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      workRecords = await window.aivicApi.list(1) || tables[1]?.records || [];
      workItems = await window.aivicApi.list(3) || tables[3]?.records || [];

      populateWorkRecords();
      populateWorkItems();
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      workRecords = tables[1]?.records || [];
      workItems = tables[3]?.records || [];
      populateWorkRecords();
      populateWorkItems();
    }
  }

  // 作業記録ドロップダウンを設定
  function populateWorkRecords() {
    const select = container.querySelector('#select-work-record');
    select.innerHTML = '<option value="">選択してください</option>';

    workRecords.forEach(record => {
      const option = document.createElement('option');
      option.value = record.作業記録ID;
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      option.textContent = `${workDate} - ${record.プロジェクト名} (${record.作業種別})`;
      select.appendChild(option);
    });
  }

  // 作業項目ドロップダウンを設定
  function populateWorkItems() {
    const select = container.querySelector('#select-work-item');
    select.innerHTML = '<option value="">選択してください</option>';

    workItems
      .filter(item => item.有効フラグ)
      .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
      .forEach(item => {
        const option = document.createElement('option');
        option.value = item.作業項目ID;
        option.textContent = `${item.作業項目コード} - ${item.作業項目名}`;
        select.appendChild(option);
      });
  }

  // 時間計算
  function calculateTimes() {
    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    if (!startTime || !endTime) {
      container.querySelector('#display-total-time').value = '';
      container.querySelector('#display-net-time').value = '';
      return;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    // 日跨ぎ対応
    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const netMinutes = Math.max(0, totalMinutes - breakTime);

    const totalHours = Math.floor(totalMinutes / 60);
    const totalMins = totalMinutes % 60;
    const netHours = Math.floor(netMinutes / 60);
    const netMins = netMinutes % 60;

    container.querySelector('#display-total-time').value = `${totalHours}時間${totalMins}分`;
    container.querySelector('#display-net-time').value = `${netHours}時間${netMins}分`;
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-display');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    container.querySelector('#warning-display').style.display = 'none';
  }

  // 警告表示
  function showWarning(message) {
    const warningDiv = container.querySelector('#warning-display');
    warningDiv.textContent = message;
    warningDiv.style.display = 'block';
    container.querySelector('#error-display').style.display = 'none';
  }

  // エラー・警告非表示
  function hideMessages() {
    container.querySelector('#error-display').style.display = 'none';
    container.querySelector('#warning-display').style.display = 'none';
  }

  // バリデーション
  function validateForm() {
    hideMessages();

    const recordId = container.querySelector('#select-work-record').value;
    if (!recordId) {
      showError('修正対象の作業記録を選択してください');
      return false;
    }

    const startTime = container.querySelector('#input-start-time').value;
    const endTime = container.querySelector('#input-end-time').value;
    const correctionReason = container.querySelector('#textarea-correction-reason').value.trim();

    if (!startTime || !endTime) {
      showError('作業開始時刻と終了時刻を入力してください');
      return false;
    }

    if (startTime === endTime) {
      showError('作業時間が0分です。開始時刻と終了時刻を確認してください。');
      return false;
    }

    const start = new Date(`2000-01-01T${startTime}`);
    let end = new Date(`2000-01-01T${endTime}`);

    if (end <= start) {
      end.setDate(end.getDate() + 1);
    }

    const totalMinutes = (end - start) / (1000 * 60);
    const breakTime = parseInt(container.querySelector('#input-break-time').value) || 0;

    if (breakTime > totalMinutes) {
      showError('中断時間が作業時間を超過しています');
      return false;
    }

    if (!correctionReason) {
      showError('修正理由を入力してください');
      return false;
    }

    if (correctionReason.length > 500) {
      showError('修正理由は500文字以内で入力してください');
      return false;
    }

    // 異常値チェック
    if (totalMinutes > 24 * 60) {
      showWarning('作業時間が24時間を超えています。確認してください。');
    }

    return true;
  }

  // 文字数カウンター更新
  function updateCharCount() {
    const textarea = container.querySelector('#textarea-correction-reason');
    const counter = container.querySelector('#reason-char-count');
    counter.textContent = textarea.value.length;
  }

  // 作業記録選択時の処理
  container.querySelector('#select-work-record').addEventListener('change', function() {
    const recordId = this.value;
    if (!recordId) {
      selectedRecord = null;
      originalData = null;
      // フォームクリア
      container.querySelector('#input-work-date').value = '';
      container.querySelector('#input-start-time').value = '';
      container.querySelector('#input-end-time').value = '';
      container.querySelector('#input-break-time').value = '';
      container.querySelector('#select-work-item').value = '';
      container.querySelector('#textarea-work-detail').value = '';
      container.querySelector('#textarea-correction-reason').value = '';
      calculateTimes();
      updateCharCount();
      hideMessages();
      return;
    }

    selectedRecord = workRecords.find(r => r.作業記録ID === recordId);
    if (selectedRecord) {
      originalData = { ...selectedRecord };

      // フォームに既存データを設定
      const workDate = new Date(selectedRecord.作業日).toLocaleDateString('ja-JP');
      container.querySelector('#input-work-date').value = workDate;

      if (selectedRecord.作業開始時刻) {
        const startTime = new Date(selectedRecord.作業開始時刻);
        container.querySelector('#input-start-time').value = startTime.toTimeString().slice(0, 5);
      }

      if (selectedRecord.作業終了時刻) {
        const endTime = new Date(selectedRecord.作業終了時刻);
        container.querySelector('#input-end-time').value = endTime.toTimeString().slice(0, 5);
      }

      // 中断時間を計算（中断記録テーブルから取得する想定だが、簡略化）
      container.querySelector('#input-break-time').value = '0';

      // 作業項目を設定（プロジェクト名から推測、または空）
      container.querySelector('#select-work-item').value = '';

      container.querySelector('#textarea-work-detail').value = selectedRecord.作業内容 || '';
      container.querySelector('#textarea-correction-reason').value = '';

      calculateTimes();
      updateCharCount();
      hideMessages();
    }
  });

  // 時間入力時の計算
  container.querySelector('#input-start-time').addEventListener('change', calculateTimes);
  container.querySelector('#input-end-time').addEventListener('change', calculateTimes);
  container.querySelector('#input-break-time').addEventListener('input', calculateTimes);

  // 文字数カウンター
  container.querySelector('#textarea-correction-reason').addEventListener('input', updateCharCount);

  // 元データ参照ボタン
  container.querySelector('#btn-view-original').addEventListener('click', function() {
    if (!originalData) {
      showError('修正対象の作業記録を選択してください');
      return;
    }

    const modal = container.querySelector('#original-data-modal');
    const content = container.querySelector('#original-data-content');

    const workDate = new Date(originalData.作業日).toLocaleDateString('ja-JP');
    const startTime = originalData.作業開始時刻 ? new Date(originalData.作業開始時刻).toTimeString().slice(0, 5) : '未設定';
    const endTime = originalData.作業終了時刻 ? new Date(originalData.作業終了時刻).toTimeString().slice(0, 5) : '未設定';

    content.innerHTML = `
      <div style="margin-bottom: 8px;"><strong>作業日:</strong> ${workDate}</div>
      <div style="margin-bottom: 8px;"><strong>開始時刻:</strong> ${startTime}</div>
      <div style="margin-bottom: 8px;"><strong>終了時刻:</strong> ${endTime}</div>
      <div style="margin-bottom: 8px;"><strong>プロジェクト名:</strong> ${originalData.プロジェクト名 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業種別:</strong> ${originalData.作業種別 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>作業内容:</strong> ${originalData.作業内容 || ''}</div>
      <div style="margin-bottom: 8px;"><strong>進捗状況:</strong> ${originalData.進捗状況 || ''}</div>
    `;

    modal.style.display = 'block';
  });

  // モーダル閉じる
  container.querySelector('#btn-close-modal').addEventListener('click', function() {
    container.querySelector('#original-data-modal').style.display = 'none';
  });

  // キャンセルボタン
  container.querySelector('#btn-cancel').addEventListener('click', function() {
    if (confirm('修正内容が破棄されます。よろしいですか？')) {
      window.showScreen("scr-1778907367889");
    }
  });

  // 保存ボタン
  container.querySelector('#btn-save').addEventListener('click', async function() {
    if (!validateForm()) return;

    try {
      const recordId = container.querySelector('#select-work-record').value;
      const startTime = container.querySelector('#input-start-time').value;
      const endTime = container.querySelector('#input-end-time').value;
      const workItemId = container.querySelector('#select-work-item').value;
      const workDetail = container.querySelector('#textarea-work-detail').value;
      const correctionReason = container.querySelector('#textarea-correction-reason').value;

      // 作業開始・終了時刻を更新
      const workDate = new Date(selectedRecord.作業日);
      const startDateTime = new Date(workDate);
      const [startHour, startMin] = startTime.split(':');
      startDateTime.setHours(parseInt(startHour), parseInt(startMin), 0, 0);

      const endDateTime = new Date(workDate);
      const [endHour, endMin] = endTime.split(':');
      endDateTime.setHours(parseInt(endHour), parseInt(endMin), 0, 0);

      // 日跨ぎ対応
      if (endDateTime <= startDateTime) {
        endDateTime.setDate(endDateTime.getDate() + 1);
      }

      const updateData = {
        作業開始時刻: startDateTime.toISOString(),
        作業終了時刻: endDateTime.toISOString(),
        作業時間: Math.floor((endDateTime - startDateTime) / (1000 * 60)),
        作業内容: workDetail,
        更新日時: new Date().toISOString(),
        更新者ID: 'current-user-id' // 実際のユーザーIDを設定
      };

      const result = await window.aivicApi.update(1, recordId, updateData);

      if (result) {
        alert('工数修正が完了しました');
        window.showScreen("scr-1778907367889");
      } else {
        showError('保存に失敗しました。もう一度お試しください。');
      }
    } catch (error) {
      console.error('保存エラー:', error);
      showError('保存中にエラーが発生しました。');
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let allWorkRecords = [];
  let allUsers = [];
  let allWorkItems = [];
  let allInterruptions = [];
  let allAnomalies = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // プレビューテーブル再描画関数
  function renderPreview(records) {
    const tbody = container.querySelector('#preview-tbody');
    const countSpan = container.querySelector('#data-count');

    countSpan.textContent = records.length;

    if (records.length === 0) {
      tbody.innerHTML = '<tr><td colspan="6" style="padding: 20px; text-align: center; color: var(--text-muted); font-size: 13px;">該当するデータが見つかりませんでした</td></tr>';
      return;
    }

    // 最大100件まで表示
    const displayRecords = records.slice(0, 100);
    tbody.innerHTML = displayRecords.map(record => {
      const user = allUsers.find(u => u.ユーザーID === record.作業員ID);
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}時間${record.作業時間 % 60}分` : '未完了';

      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${user?.氏名 || '不明'}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workDate}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${workTime}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.作業場所 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.作業内容 || ''}</td>
          <td style="padding: 6px 10px; font-size: 13px; color: var(--text);">${record.進捗状況 || ''}</td>
        </tr>
      `;
    }).join('');

    if (records.length > 100) {
      tbody.innerHTML += `<tr><td colspan="6" style="padding: 8px 10px; text-align: center; color: var(--text-muted); font-size: 12px;">※ ${records.length}件中100件を表示</td></tr>`;
    }
  }

  // 条件プレビュー更新
  function updateConditionPreview() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const outputFormat = container.querySelector('#output-format').value;
    const workLocation = container.querySelector('#work-location').value;
    const includeAnomaly = container.querySelector('#include-anomaly').checked;
    const includeInterruption = container.querySelector('#include-interruption').checked;

    const workerSelect = container.querySelector('#worker-select');
    const selectedWorkers = Array.from(workerSelect.selectedOptions).map(opt => opt.text);

    const workItemSelect = container.querySelector('#work-item-select');
    const selectedWorkItems = Array.from(workItemSelect.selectedOptions).map(opt => opt.text);

    let preview = [];

    if (startDate && endDate) {
      preview.push(`期間: ${startDate} ～ ${endDate}`);
    }

    if (selectedWorkers.length > 0) {
      preview.push(`作業員: ${selectedWorkers.join(', ')}`);
    }

    if (selectedWorkItems.length > 0) {
      preview.push(`作業項目: ${selectedWorkItems.join(', ')}`);
    }

    if (workLocation) {
      preview.push(`作業場所: ${workLocation}`);
    }

    if (outputFormat) {
      preview.push(`出力形式: ${outputFormat.toUpperCase()}`);
    }

    preview.push(`異常値データ: ${includeAnomaly ? '含む' : '除外'}`);
    preview.push(`中断記録: ${includeInterruption ? '含む' : '除外'}`);

    const previewDiv = container.querySelector('#condition-preview');
    previewDiv.textContent = preview.length > 0 ? preview.join(' | ') : '条件を設定してください';
  }

  // データフィルタリング
  function filterData() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const workLocation = container.querySelector('#work-location').value;
    const includeAnomaly = container.querySelector('#include-anomaly').checked;
    const includeInterruption = container.querySelector('#include-interruption').checked;

    const workerSelect = container.querySelector('#worker-select');
    const selectedWorkerIds = Array.from(workerSelect.selectedOptions).map(opt => opt.value);

    const workItemSelect = container.querySelector('#work-item-select');
    const selectedWorkItemIds = Array.from(workItemSelect.selectedOptions).map(opt => opt.value);

    let filtered = [...allWorkRecords];

    // 期間フィルタ
    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      filtered = filtered.filter(record => {
        const workDate = new Date(record.作業日);
        return workDate >= start && workDate <= end;
      });
    }

    // 作業員フィルタ
    if (selectedWorkerIds.length > 0) {
      filtered = filtered.filter(record => selectedWorkerIds.includes(record.作業員ID));
    }

    // 作業場所フィルタ
    if (workLocation) {
      filtered = filtered.filter(record => 
        record.作業場所 && record.作業場所.includes(workLocation)
      );
    }

    // 異常値フィルタ
    if (!includeAnomaly) {
      const anomalyRecordIds = allAnomalies.map(a => a.検出対象レコードID);
      filtered = filtered.filter(record => !anomalyRecordIds.includes(record.作業記録ID));
    }

    // 中断記録フィルタ
    if (!includeInterruption) {
      const interruptionRecordIds = allInterruptions.map(i => i.作業記録ID);
      filtered = filtered.filter(record => !interruptionRecordIds.includes(record.作業記録ID));
    }

    return filtered;
  }

  // バリデーション
  function validateConditions() {
    const startDate = container.querySelector('#start-date').value;
    const endDate = container.querySelector('#end-date').value;
    const outputFormat = container.querySelector('#output-format').value;
    const workerSelect = container.querySelector('#worker-select');
    const selectedWorkers = Array.from(workerSelect.selectedOptions);

    if (!startDate || !endDate) {
      showError('抽出期間を指定してください');
      return false;
    }

    if (new Date(startDate) > new Date(endDate)) {
      showError('開始日は終了日より前の日付を入力してください');
      return false;
    }

    if (selectedWorkers.length === 0) {
      showError('作業員を選択してください');
      return false;
    }

    if (!outputFormat) {
      showError('出力形式を選択してください');
      return false;
    }

    return true;
  }

  // CSV/Excel出力
  function exportData(records, format) {
    if (records.length === 0) {
      showError('出力するデータがありません');
      return;
    }

    // 最大件数チェック（10000件）
    if (records.length > 10000) {
      showError('抽出件数が上限（10,000件）を超えています。条件を絞り込んでください。');
      return;
    }

    const headers = ['作業員名', '作業日', '作業開始時刻', '作業終了時刻', '作業時間', '作業場所', '作業種別', '作業内容', '進捗状況'];

    const csvData = records.map(record => {
      const user = allUsers.find(u => u.ユーザーID === record.作業員ID);
      const workDate = new Date(record.作業日).toLocaleDateString('ja-JP');
      const startTime = record.作業開始時刻 ? new Date(record.作業開始時刻).toLocaleString('ja-JP') : '';
      const endTime = record.作業終了時刻 ? new Date(record.作業終了時刻).toLocaleString('ja-JP') : '';
      const workTime = record.作業時間 ? `${Math.floor(record.作業時間 / 60)}:${String(record.作業時間 % 60).padStart(2, '0')}` : '';

      return [
        user?.氏名 || '不明',
        workDate,
        startTime,
        endTime,
        workTime,
        record.作業場所 || '',
        record.作業種別 || '',
        record.作業内容 || '',
        record.進捗状況 || ''
      ];
    });

    const csvContent = [headers, ...csvData]
      .map(row => row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(','))
      .join('\n');

    const bom = '\uFEFF';
    const blob = new Blob([bom + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);

    const now = new Date();
    const timestamp = now.toISOString().slice(0, 19).replace(/[:-]/g, '');
    const filename = `工数記録データ_${timestamp}.${format}`;

    link.setAttribute('download', filename);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }

  // 条件クリア
  function clearConditions() {
    container.querySelector('#start-date').value = '';
    container.querySelector('#end-date').value = '';
    container.querySelector('#output-format').value = '';
    container.querySelector('#work-location').value = '';
    container.querySelector('#include-anomaly').checked = false;
    container.querySelector('#include-interruption').checked = false;
    container.querySelector('#worker-select').selectedIndex = -1;
    container.querySelector('#work-item-select').selectedIndex = -1;

    updateConditionPreview();
    renderPreview([]);
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 作業記録データ
      const workRecords = await window.aivicApi.list(1);
      if (workRecords) allWorkRecords = workRecords;

      // ユーザーデータ
      const users = await window.aivicApi.list(0);
      if (users) allUsers = users;

      // 作業項目マスタ
      const workItems = await window.aivicApi.list(3);
      if (workItems) allWorkItems = workItems;

      // 中断記録
      const interruptions = await window.aivicApi.list(2);
      if (interruptions) allInterruptions = interruptions;

      // 異常値検出ログ
      const anomalies = await window.aivicApi.list(4);
      if (anomalies) allAnomalies = anomalies;

      // セレクトボックス初期化
      const workerSelect = container.querySelector('#worker-select');
      workerSelect.innerHTML = allUsers.map(user => 
        `<option value="${user.ユーザーID}">${user.氏名}</option>`
      ).join('');

      const workItemSelect = container.querySelector('#work-item-select');
      workItemSelect.innerHTML = allWorkItems
        .filter(item => item.有効フラグ)
        .sort((a, b) => (a.表示順序 || 0) - (b.表示順序 || 0))
        .map(item => 
          `<option value="${item.作業項目ID}">${item.作業項目名}</option>`
        ).join('');

    } catch (error) {
      console.error('データ読み込みエラー:', error);
    }
  }

  // イベントリスナー設定
  container.querySelector('#start-date').addEventListener('change', updateConditionPreview);
  container.querySelector('#end-date').addEventListener('change', updateConditionPreview);
  container.querySelector('#output-format').addEventListener('change', updateConditionPreview);
  container.querySelector('#work-location').addEventListener('input', updateConditionPreview);
  container.querySelector('#include-anomaly').addEventListener('change', updateConditionPreview);
  container.querySelector('#include-interruption').addEventListener('change', updateConditionPreview);
  container.querySelector('#worker-select').addEventListener('change', updateConditionPreview);
  container.querySelector('#work-item-select').addEventListener('change', updateConditionPreview);

  // プレビューボタン
  container.querySelector('#btn-preview').addEventListener('click', () => {
    const filtered = filterData();
    renderPreview(filtered);
    updateConditionPreview();
  });

  // 抽出実行ボタン
  container.querySelector('#btn-extract').addEventListener('click', () => {
    if (!validateConditions()) return;

    const filtered = filterData();
    const format = container.querySelector('#output-format').value;

    // タイムアウトシミュレーション（大量データの場合）
    if (filtered.length > 50000) {
      setTimeout(() => {
        showError('処理がタイムアウトしました。条件を絞り込んで再実行してください。');
      }, 30000);
      return;
    }

    exportData(filtered, format);
  });

  // 条件クリアボタン
  container.querySelector('#btn-clear').addEventListener('click', clearConditions);

  // 条件保存ボタン
  container.querySelector('#btn-save-condition').addEventListener('click', () => {
    const modal = container.querySelector('#save-condition-modal');
    modal.style.display = 'flex';
    container.querySelector('#condition-name').focus();
  });

  // 条件保存モーダル
  container.querySelector('#btn-cancel-save').addEventListener('click', () => {
    container.querySelector('#save-condition-modal').style.display = 'none';
    container.querySelector('#condition-name').value = '';
  });

  container.querySelector('#btn-confirm-save').addEventListener('click', () => {
    const conditionName = container.querySelector('#condition-name').value.trim();
    if (!conditionName) {
      showError('条件名を入力してください');
      return;
    }

    // 条件保存処理（実際の実装では保存APIを呼ぶ）
    container.querySelector('#save-condition-modal').style.display = 'none';
    container.querySelector('#condition-name').value = '';

    // 成功メッセージ表示
    const successDiv = document.createElement('div');
    successDiv.textContent = '条件が保存されました';
    successDiv.style.cssText = 'position: fixed; top: 20px; right: 20px; background: var(--primary); color: #fff; padding: 8px 16px; border-radius: 6px; font-size: 13px; z-index: 1001;';
    document.body.appendChild(successDiv);
    setTimeout(() => {
      document.body.removeChild(successDiv);
    }, 3000);
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    window.showScreen("scr-1778907145716");
  });

  // 初期化
  loadInitialData();
  updateConditionPreview();
}
